insert into public.life_moments (id, title, body, icon, speaker, kind, conditions, path_w, choices, cooldown_days, weight, sort) values
($t$d_keke_change$t$, $t$No change, oga$t$, $t$You jump a keke from Ugbowo to Ring Road with only a ₦1,000 note for a ₦300 fare. The driver pats his pockets and sighs. "No change o, boss. Make I find am small small." Traffic is crawling anyway.$t$, $t$🛺$t$, $t$Keke driver, Ugbowo$t$, $t$daily$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"wait","label":"Wait while he finds change","path":{"goodwill":1},"outcomes":[{"w":60,"text":"He runs to a buka and comes back sweating, with your change and a big apology. You part as friends.","tone":"good","effects":[{"t":"needs","delta":{"social":3}}]},{"w":25,"text":"While he searches, a hawker sells you hot groundnut at \"special price\". Your change turns into boli. Still, na sweet snack.","tone":"funny","effects":[{"t":"cash","amount":-300,"up_to":true},{"t":"needs","delta":{"hunger":8,"fun":3}}]},{"w":15,"text":"The keke dies at the junction and you help him push it. He refuses your fare and says, \"I go remember you.\"","tone":"twist","effects":[{"t":"path","delta":{"goodwill":2}},{"t":"follow_up","moment":"c_keke_thanks","delay_hours":72,"chance":70}],"path_w":{"goodwill":1.5}}]},{"id":"keep","label":"Tell him to keep the change","cost":700,"path":{"goodwill":3},"outcomes":[{"w":70,"text":"He shouts blessings at you until the next junction. For a minute, the whole keke feels warm.","tone":"good","effects":[{"t":"needs","delta":{"social":4,"stress":-3}},{"t":"follow_up","moment":"c_keke_thanks","delay_hours":96,"chance":55}]},{"w":30,"text":"A market woman on the back seat saw everything. At Ring Road she presses ₦1,500 into your hand: \"For your good heart, my pikin.\"","tone":"twist","effects":[{"t":"cash","amount":1500},{"t":"path","delta":{"luck":1}}],"path_w":{"goodwill":1}}]},{"id":"argue","label":"Argue about the change","path":{"trouble":1,"goodwill":-1},"outcomes":[{"w":55,"text":"The whole keke joins the argument. You arrive late, hoarse, and ₦300 poorer after \"fine\" nobody can explain.","tone":"bad","effects":[{"t":"cash","amount":-300,"up_to":true},{"t":"needs","delta":{"stress":8}}]},{"w":35,"text":"A passenger starts judging you both like Nollywood. Everybody laughs, the driver finds your change, and you shake hands.","tone":"funny","effects":[{"t":"needs","delta":{"fun":6,"stress":-2}}]},{"w":10,"text":"The driver admits he had change the whole time and was just testing you. He gives it back with a grin.","tone":"good","effects":[{"t":"needs","delta":{"stress":-2}}]}]}]$j$::jsonb, 25, 1, 400),
($t$d_okada_shortcut$t$, $t$The Ikpoba Hill shortcut$t$, $t$You are running late. A young rider revs beside you: "Boss, I know one shortcut through Ikpoba Hill. Five minutes, I swear. Na ₦1,500." The main road is a go-slow, but the shortcut looks narrow.$t$, $t$🏍️$t$, $t$A rider you do not know$t$, $t$daily$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"shortcut","label":"Take the shortcut","cost":1500,"path":{"hustle":3,"trouble":1},"outcomes":[{"w":40,"text":"You fly through back streets, dodge two goats and one grandmother, and arrive early. The rider collects his money and winks.","tone":"good","effects":[{"t":"needs","delta":{"stress":-4,"fun":5}},{"t":"skill_xp","skill":"driving","xp":3}],"path_w":{"luck":1}},{"w":40,"text":"Halfway, the bike drops into a pothole and your elbow meets the road. You make it, but sore and dusty.","tone":"bad","effects":[{"t":"needs","delta":{"health":-8,"stress":6,"hygiene":-10}}],"path_w":{"luck":-1}},{"w":20,"text":"The shortcut ends at a locked gate. You walk back with the rider, laughing and cursing at the same time. He refunds half.","tone":"twist","effects":[{"t":"cash","amount":750},{"t":"needs","delta":{"fun":4,"social":3}}]}]},{"id":"main","label":"Stay on the main road","path":{"hustle":-2},"outcomes":[{"w":60,"text":"The go-slow is long, but you reach safely. You use the time to reply messages and breathe.","tone":"good","effects":[{"t":"needs","delta":{"stress":-2}}]},{"w":40,"text":"Stuck beside a bus, you watch a man argue with his own umbrella for ten minutes. Best free comedy in Benin.","tone":"funny","effects":[{"t":"needs","delta":{"fun":6}}]}]},{"id":"walk","label":"Say no and walk","path":{"hustle":-1,"faith":1},"outcomes":[{"w":100,"text":"You walk, buy pure water on the way and arrive late but calm. Your legs thank you.","tone":"good","effects":[{"t":"needs","delta":{"health":3,"energy":-5,"stress":-3}}]}]}]$j$::jsonb, 30, 1, 401),
($t$d_nepa_night$t$, $t$NEPA don take light again$t$, $t$Evening, and the light goes off with that sad little click. The whole compound groans. Mr. Osaze next door starts his small generator, then coughs: he has almost no fuel left.$t$, $t$💡$t$, $t$Your compound$t$, $t$daily$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"share","label":"Help him buy fuel","cost":1200,"path":{"goodwill":3,"family":1},"outcomes":[{"w":60,"text":"His generator roars. He lets the whole compound charge phones, and your name is mentioned in three separate prayers.","tone":"good","effects":[{"t":"needs","delta":{"social":6,"stress":-4}}]},{"w":40,"text":"Mr. Osaze says he will not forget this. Two days later he knocks on your door with something in a nylon bag.","tone":"twist","effects":[{"t":"path","delta":{"luck":1}},{"t":"follow_up","moment":"c_neighbour_repays","delay_hours":60,"chance":80}],"path_w":{"goodwill":1.5}}]},{"id":"torch","label":"Bring a torch and sit outside","path":{"goodwill":1},"outcomes":[{"w":55,"text":"The compound gathers outside to gist. Somebody brings roasted corn, somebody tells a ridiculous story about a snake. Light returns at midnight, nobody cares.","tone":"good","effects":[{"t":"needs","delta":{"social":8,"fun":6,"stress":-3}}]},{"w":45,"text":"You trip over a bucket in the dark and tell no one. The corn was sweet though.","tone":"funny","effects":[{"t":"needs","delta":{"social":4,"fun":3,"hunger":5}}]}]},{"id":"sleep","label":"Sleep early and ignore everything","path":{"hustle":-1},"outcomes":[{"w":55,"text":"Without the fan it is hot, but you drift off. Light returns at 3 am and the fan wakes you with a happy hum.","tone":"good","effects":[{"t":"needs","delta":{"energy":8,"stress":-2}}]},{"w":45,"text":"Mosquitoes hold a conference around your ears. You wake up tired and furious at nobody in particular.","tone":"bad","effects":[{"t":"needs","delta":{"energy":-5,"stress":6}}]}]}]$j$::jsonb, 20, 1, 402),
($t$d_landlord_rise$t$, $t$Landlord wants more$t$, $t$Your landlord catches you at the gate with a folded paper. "Things are costly now, so rent must go up small." His smile is polite. His eyes are counting money.$t$, $t$🏠$t$, $t$Landlord, Ekenwan Road$t$, $t$daily$t$, $j${"min_days":2}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"negotiate","label":"Negotiate like a market woman","path":{"hustle":2},"outcomes":[{"w":40,"text":"You talk about the broken tap, the leaking roof and your loyalty. He laughs and agrees to keep the rent as it is, for now.","tone":"good","effects":[{"t":"needs","delta":{"stress":-6}},{"t":"skill_xp","skill":"charisma","xp":4}],"path_w":{"luck":1}},{"w":40,"text":"He pretends not to hear you. The new rent stands and he adds a \"levy\" for the compound bin.","tone":"bad","effects":[{"t":"cash","amount":-1500,"up_to":true},{"t":"needs","delta":{"stress":6}}]},{"w":20,"text":"He softens, and offers a deal: help him fix the compound gate and he forgets the increase this month.","tone":"twist","effects":[{"t":"needs","delta":{"energy":-8,"stress":-4}},{"t":"path","delta":{"goodwill":1}}]}]},{"id":"gift","label":"Greet him with a small gift","cost":1000,"path":{"goodwill":1,"trouble":-1},"outcomes":[{"w":70,"text":"A bag of oranges works wonders. He talks about his own landlord days and lets you off easy.","tone":"good","effects":[{"t":"needs","delta":{"social":4,"stress":-4}}]},{"w":30,"text":"He takes the oranges, thanks you, and raises the rent anyway. \"Business is business,\" he says, peeling one.","tone":"funny","effects":[{"t":"needs","delta":{"stress":3,"fun":2}}]}]},{"id":"dodge","label":"Dodge him for a few days","path":{"trouble":1,"goodwill":-1},"outcomes":[{"w":60,"text":"He waits at your door at 6 am with a flask of tea and a long face. The talk is not nice.","tone":"bad","effects":[{"t":"needs","delta":{"stress":10}},{"t":"cash","amount":-800,"up_to":true}]},{"w":40,"text":"You hide behind the generator house for ten minutes. He walks past three times. You have never felt more like a spy.","tone":"funny","effects":[{"t":"needs","delta":{"fun":4,"stress":2}}]}]}]$j$::jsonb, 45, 1, 403),
($t$d_oba_market_haggle$t$, $t$Tomatoes at Oba Market$t$, $t$Oba Market is loud this morning. Mama Ngozi shows you a basket of fresh tomatoes and names a price that feels like highway robbery. Behind you, a woman is already pushing to buy the same basket.$t$, $t$🍅$t$, $t$Mama Ngozi, Oba Market$t$, $t$daily$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"haggle","label":"Haggle hard","path":{"hustle":2},"outcomes":[{"w":45,"text":"You walk away twice and she calls you back twice. You pay ₦400 less than she first said, and she gives you pepper for \"your stubborn mouth\".","tone":"good","effects":[{"t":"needs","delta":{"fun":4}},{"t":"item","id":"pepper","qty":1},{"t":"skill_xp","skill":"business","xp":3}]},{"w":35,"text":"She hisses, says you are insulting her children, and sells the basket to the woman behind you. You leave with nothing and a red face.","tone":"bad","effects":[{"t":"needs","delta":{"stress":6,"social":-3}}]},{"w":20,"text":"The haggling draws a crowd. Someone claps. Somebody else starts bidding, and the tomatoes go for double. You buy a small one in shame.","tone":"funny","effects":[{"t":"cash","amount":-300,"up_to":true},{"t":"needs","delta":{"fun":6}}]}]},{"id":"full","label":"Pay her price and be done","cost":1400,"path":{"goodwill":1},"outcomes":[{"w":65,"text":"Mama Ngozi smiles, adds three extra tomatoes and tells you to come back on Saturday.","tone":"good","effects":[{"t":"needs","delta":{"hunger":6,"social":3}},{"t":"item","id":"tomatoes","qty":2}]},{"w":35,"text":"As you leave, she whispers: \"Come early Saturday. I keep the best ones for people who do not shout.\" You file that away.","tone":"twist","effects":[{"t":"path","delta":{"luck":1}},{"t":"needs","delta":{"social":3}}]}]},{"id":"share","label":"Buy a second basket for a neighbour","cost":2600,"path":{"goodwill":3,"family":1},"outcomes":[{"w":70,"text":"Your neighbour almost cries when you hand it over. The whole street will be eating stew tonight, and your name is in it.","tone":"good","effects":[{"t":"needs","delta":{"social":7,"stress":-4}}]},{"w":30,"text":"Your neighbour insists on paying you back with a small cash gift and a promise of jollof on Sunday.","tone":"twist","effects":[{"t":"cash","amount":1200},{"t":"needs","delta":{"social":5}}]}]}]$j$::jsonb, 20, 1, 404),
($t$d_ring_road_boy$t$, $t$The fallen basket at Ring Road$t$, $t$At the Ring Road junction a boy of about fifteen trips and his tray of sachet water hits the tarmac. Bottles roll everywhere. Cars honk. Some people laugh, some film, nobody helps.$t$, $t$🧺$t$, $t$Ring Road$t$, $t$daily$t$, $j${}$j$::jsonb, $j${"goodwill":0.8}$j$::jsonb, $j$[{"id":"help","label":"Drop everything and help","path":{"goodwill":4},"outcomes":[{"w":55,"text":"You pick up bottles between cars until the tray is full again. He bows his head. \"God go bless you, sir.\" Your hands are dirty and your chest feels clean.","tone":"good","effects":[{"t":"needs","delta":{"social":4,"energy":-4,"hygiene":-6}},{"t":"street_cred","delta":1}]},{"w":45,"text":"He insists on writing your name in his small notebook. \"When I am big, I go find you,\" he says, very serious.","tone":"twist","effects":[{"t":"needs","delta":{"social":5}},{"t":"path","delta":{"luck":1}},{"t":"follow_up","moment":"c_boy_bank","delay_hours":120,"chance":85}],"path_w":{"goodwill":1.5}}]},{"id":"buy","label":"Buy what is left, and move on","cost":1500,"path":{"goodwill":2},"outcomes":[{"w":70,"text":"You buy ten sachets. He thanks you, relieved, and you share the water with whoever you meet next.","tone":"good","effects":[{"t":"needs","delta":{"social":3,"hunger":2}}]},{"w":30,"text":"You buy a dozen sachets and realise you now own enough water to start a small borehole. Your neighbours are very happy later.","tone":"funny","effects":[{"t":"needs","delta":{"social":4,"fun":3}}]}]},{"id":"walk","label":"Walk on. You are late","path":{"goodwill":-2},"outcomes":[{"w":60,"text":"You tell yourself it is not your business. All day the boy’s face follows you, and your appointment does not even start on time.","tone":"bad","effects":[{"t":"needs","delta":{"stress":6}},{"t":"path","delta":{"luck":-1}}]},{"w":40,"text":"You walk on, a bit guilty, and you do make your meeting on time. Life continues.","tone":"good","effects":[{"t":"needs","delta":{"stress":1}}]}]}]$j$::jsonb, 45, 1, 405),
($t$d_cheap_phone$t$, $t$A very cheap phone$t$, $t$At New Benin Market a smiling guy shows you a smartphone, still in a nylon bag. "Brand new, boss. ₦8,000 only, my brother is traveling." The screen is spotless. The box is missing. The story is a bit too smooth.$t$, $t$📱$t$, $t$A guy at New Benin Market$t$, $t$daily$t$, $j${"min_cash":8000}$j$::jsonb, $j${"trouble":0.6,"hustle":0.5}$j$::jsonb, $j$[{"id":"buy","label":"Buy it, na bargain","cost":8000,"path":{"hustle":2,"trouble":2},"outcomes":[{"w":40,"text":"It works fine! You charge it, set it up, and feel like you won the lottery. Maybe it really was a good day.","tone":"good","effects":[{"t":"needs","delta":{"fun":8,"stress":-3}},{"t":"path","delta":{"luck":1}}],"path_w":{"luck":1}},{"w":40,"text":"The phone works fine at first. You use it happily for a few days, but something at the back of your mind keeps itching.","tone":"twist","effects":[{"t":"needs","delta":{"fun":4}},{"t":"follow_up","moment":"c_phone_police","delay_hours":96,"chance":100}],"path_w":{"trouble":1.2}},{"w":20,"text":"It dies in an hour. The guy is gone, and so is the money.","tone":"bad","effects":[{"t":"needs","delta":{"stress":8,"fun":-4}}]}]},{"id":"check","label":"Ask for the receipt","path":{"trouble":-1,"hustle":-1},"outcomes":[{"w":60,"text":"He suddenly remembers an urgent call and disappears into the crowd. You smile and keep your money.","tone":"good","effects":[{"t":"needs","delta":{"stress":-2}},{"t":"street_cred","delta":1}]},{"w":40,"text":"He produces a \"receipt\" written on a cigarette pack. You have never been so impressed and so unconvinced.","tone":"funny","effects":[{"t":"needs","delta":{"fun":5}}]}]},{"id":"report","label":"Quietly tell the market security","path":{"goodwill":1,"trouble":-2},"outcomes":[{"w":50,"text":"Two men in blue shirts follow him. Later, the market association thanks you for being observant.","tone":"good","effects":[{"t":"street_cred","delta":2},{"t":"needs","delta":{"social":4}}]},{"w":50,"text":"By the time the security arrives, the seller has vanished. They shrug and say, \"Thank you, we go look into it.\"","tone":"bad","effects":[{"t":"needs","delta":{"stress":2}}]}]}]$j$::jsonb, 40, 1, 406),
($t$d_uniben_exam$t$, $t$Exam hall at UNIBEN$t$, $t$The exam is in an hour and your head is full of fog. Your friend Osa, the class genius, offers you his notes. Another coursemate whispers about "a way to see the questions early". The invigilator is already in the hall.$t$, $t$🎓$t$, $t$UNIBEN, Ugbowo Campus$t$, $t$daily$t$, $j${"school":true}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"notes","label":"Borrow Osa’s notes and read hard","path":{"hustle":1,"goodwill":1},"outcomes":[{"w":60,"text":"You cram sharp sharp and the questions turn out to be the ones Osa predicted. You walk out confident.","tone":"good","effects":[{"t":"needs","delta":{"stress":-4,"energy":-6}},{"t":"skill_xp","skill":"teaching","xp":3}]},{"w":40,"text":"The notes are good but you wake up too late. You write half the paper from memory and the rest from hope.","tone":"bad","effects":[{"t":"needs","delta":{"stress":8,"energy":-8}}]}]},{"id":"early","label":"Join the \"early questions\" plan","cost":2000,"path":{"trouble":4,"goodwill":-1},"outcomes":[{"w":55,"text":"The \"plan\" was a lie. The coursemate collected money from five people and vanished. The exam is brutal.","tone":"bad","effects":[{"t":"needs","delta":{"stress":10}},{"t":"path","delta":{"luck":-1}}]},{"w":45,"text":"You are caught outside the hall with a suspicious paper. The lecturer gives you a long, quiet lecture, and a warning on record.","tone":"twist","effects":[{"t":"needs","delta":{"stress":8}},{"t":"street_cred","delta":-1},{"t":"follow_up","moment":"c_exam_warning","delay_hours":72,"chance":80}],"path_w":{"trouble":1.5}}]},{"id":"pray","label":"Pray, and write what you know","path":{"faith":3},"outcomes":[{"w":55,"text":"Your mind clears as you enter the hall. You finish with ten minutes to spare and a calm heart.","tone":"good","effects":[{"t":"needs","delta":{"stress":-6,"energy":-4}}],"path_w":{"faith":1}},{"w":45,"text":"You pass, but not with the score you hoped for. A lecturer tells you in the corridor that she likes your honest answers.","tone":"twist","effects":[{"t":"needs","delta":{"stress":2}},{"t":"skill_xp","skill":"teaching","xp":4}]}]}]$j$::jsonb, 30, 1, 407),
($t$d_church_harvest$t$, $t$Harvest Sunday$t$, $t$It is harvest Sunday. Baskets of yam and plantain line the altar. The choir is loud and the usher is working through the rows with the offering bowl. A widow in the next row looks at her purse, then at the bowl.$t$, $t$⛪$t$, $t$Church, Uselu$t$, $t$daily$t$, $j${}$j$::jsonb, $j${"faith":0.8}$j$::jsonb, $j$[{"id":"give","label":"Give generously","cost":3000,"path":{"faith":3,"goodwill":2},"outcomes":[{"w":65,"text":"The pastor says \"Amen\", and a calm settles in your chest. The widow squeezes your hand.","tone":"good","effects":[{"t":"needs","delta":{"stress":-8,"social":5}}]},{"w":35,"text":"After service the widow presses a small bag of yam into your hands. \"God sees,\" she says. You cannot refuse.","tone":"twist","effects":[{"t":"item","id":"yam","qty":1},{"t":"path","delta":{"luck":1}},{"t":"needs","delta":{"social":5}}],"path_w":{"faith":1}}]},{"id":"small","label":"Give what you can and help the widow","cost":1000,"path":{"faith":1,"goodwill":3},"outcomes":[{"w":70,"text":"You quietly cover the widow’s offering. Nobody notices but her, and she looks at you like family.","tone":"good","effects":[{"t":"needs","delta":{"social":6,"stress":-4}}]},{"w":30,"text":"The widow turns out to be the choir master’s mother. Later, the choir sings your name by accident, and everyone laughs.","tone":"twist","effects":[{"t":"needs","delta":{"social":8,"fun":5}}]}]},{"id":"keep","label":"Keep your money this week","path":{"goodwill":-1,"faith":-1},"outcomes":[{"w":55,"text":"The bowl passes. You tell yourself you will give next week. The widow does not look at you.","tone":"bad","effects":[{"t":"needs","delta":{"stress":3}}]},{"w":45,"text":"You enjoy the music and the dancing and the free puff-puff after service. No guilt, no gift.","tone":"good","effects":[{"t":"needs","delta":{"fun":6,"hunger":5}}]}]}]$j$::jsonb, 30, 1, 408),
($t$d_owambe_invite$t$, $t$Owambe in GRA$t$, $t$Madam Ivie is marrying off her daughter this Saturday and your name is on the guest list. Aso-ebi is ₦6,000. The jollof is free. "Come and show your face," she says, "even if you only come for rice."$t$, $t$🎉$t$, $t$Madam Ivie$t$, $t$daily$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"go","label":"Buy the aso-ebi and go","cost":6000,"path":{"family":1,"goodwill":1},"outcomes":[{"w":50,"text":"You dance until your feet complain. The jollof is perfect and the DJ plays your favourite old song.","tone":"good","effects":[{"t":"needs","delta":{"fun":20,"social":15,"hunger":15,"energy":-10}},{"t":"skill_xp","skill":"charisma","xp":4}]},{"w":30,"text":"At the high table you meet a man who runs three shops. You exchange numbers, and he says he will \"keep you in mind\".","tone":"twist","effects":[{"t":"needs","delta":{"fun":12,"social":12,"hunger":10}},{"t":"path","delta":{"luck":1,"hustle":1}},{"t":"follow_up","moment":"c_owambe_contact","delay_hours":96,"chance":50}]},{"w":20,"text":"Somebody steps on your new shoes, and somebody else spills stew on your aso-ebi. You smile through it. Mostly.","tone":"bad","effects":[{"t":"needs","delta":{"fun":8,"social":8,"stress":5,"hunger":8}}]}]},{"id":"gift","label":"Send a ₦1,000 gift","cost":1000,"path":{"family":1},"outcomes":[{"w":100,"text":"Madam Ivie thanks you by phone and adds, \"Next time you must come yourself.\"","tone":"good","effects":[{"t":"needs","delta":{"social":4}}]}]},{"id":"skip","label":"Say you have another event","path":{"family":-1,"goodwill":-1},"outcomes":[{"w":45,"text":"Madam Ivie says she understands. Her voice says otherwise.","tone":"bad","effects":[{"t":"needs","delta":{"social":-3}}]},{"w":55,"text":"There is no other event. You stay home with beans and a movie and you have the best Saturday of your life.","tone":"funny","effects":[{"t":"needs","delta":{"fun":10,"energy":5,"hunger":8}}]}]}]$j$::jsonb, 25, 1, 409),
($t$d_family_money$t$, $t$Mama is calling$t$, $t$Your cousin Eghe calls late. "Abeg, my small brother needs school fees. It is ₦5,000. I will pay you back at month end, I swear on my mother." You know his month end is long.$t$, $t$📞$t$, $t$Your cousin, on the phone$t$, $t$daily$t$, $j${"min_cash":5000}$j$::jsonb, $j${"family":0.8}$j$::jsonb, $j$[{"id":"full","label":"Send ₦5,000","cost":5000,"path":{"family":3,"goodwill":2},"outcomes":[{"w":55,"text":"Eghe cries, laughs, and prays for you all in one breath. The boy resumes school on Monday.","tone":"good","effects":[{"t":"needs","delta":{"social":6,"stress":-5}}]},{"w":25,"text":"Month end comes, and, to your shock, a transfer arrives with a note: \"Told you I go pay.\" It is only half, but it is something.","tone":"twist","effects":[{"t":"cash","amount":2500},{"t":"needs","delta":{"social":5}},{"t":"path","delta":{"luck":1}}],"path_w":{"family":1}},{"w":20,"text":"Two days later he calls again for \"just one more small thing\". The money is gone, and so is some of your patience.","tone":"bad","effects":[{"t":"needs","delta":{"stress":6}}]}]},{"id":"part","label":"Send ₦1,500 and explain","cost":1500,"path":{"family":1,"goodwill":1},"outcomes":[{"w":70,"text":"Eghe thanks you and says it will help a little. He sounds less desperate than before.","tone":"good","effects":[{"t":"needs","delta":{"social":3}}]},{"w":30,"text":"Eghe says \"God bless you\" in the tone people use when they wanted ₦5,000. You decide to laugh about it later.","tone":"funny","effects":[{"t":"needs","delta":{"stress":2,"fun":1}}]}]},{"id":"no","label":"Say you cannot help this time","path":{"family":-2},"outcomes":[{"w":55,"text":"The call ends cold. Your aunty will hear about it before Sunday.","tone":"bad","effects":[{"t":"needs","delta":{"stress":6,"social":-4}}]},{"w":45,"text":"He understands, says \"no wahala\", and surprises you by asking about your own life instead. You talk for an hour.","tone":"good","effects":[{"t":"needs","delta":{"social":5,"stress":-3}}]}]}]$j$::jsonb, 20, 1, 410),
($t$d_lost_wallet$t$, $t$A wallet on Airport Road$t$, $t$Walking along Airport Road you spot a brown leather wallet near a gutter. Inside: a driver’s licence, a few cards, a folded ₦10,000 note and a family photo. Nobody is looking. Or maybe somebody is.$t$, $t$👛$t$, $t$Airport Road$t$, $t$daily$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"return","label":"Find the owner and return it","path":{"goodwill":4,"trouble":-2},"outcomes":[{"w":45,"text":"The licence has an address two streets away. A relieved man opens the gate and gives you ₦3,000 \"for your trouble\".","tone":"good","effects":[{"t":"cash","amount":3000},{"t":"needs","delta":{"social":5}},{"t":"street_cred","delta":1}]},{"w":45,"text":"The owner is a retired teacher. He offers you tea, a long lecture on honesty and his phone number \"in case you ever need a friend\".","tone":"twist","effects":[{"t":"needs","delta":{"social":7,"stress":-4}},{"t":"path","delta":{"luck":1}},{"t":"follow_up","moment":"c_wallet_owner","delay_hours":120,"chance":70}],"path_w":{"goodwill":1.5}},{"w":10,"text":"The address is wrong. After two hours of walking you hand it to the nearest station. Your feet are not happy.","tone":"bad","effects":[{"t":"needs","delta":{"energy":-8,"stress":3}},{"t":"street_cred","delta":1}]}]},{"id":"keep","label":"Take the cash and drop the wallet","path":{"goodwill":-3,"trouble":3},"outcomes":[{"w":35,"text":"You pocket ₦10,000 and walk calmly. For some reason, your heart is racing.","tone":"good","effects":[{"t":"cash","amount":10000},{"t":"needs","delta":{"stress":8}}]},{"w":65,"text":"A man on a bike has been watching. \"I saw you,\" he says. You hand over ₦4,000 to keep his mouth shut and lose your appetite.","tone":"bad","effects":[{"t":"cash","amount":-4000,"up_to":true},{"t":"needs","delta":{"stress":12}},{"t":"street_cred","delta":-2}],"path_w":{"trouble":1}}]},{"id":"police","label":"Hand it to the police","path":{"goodwill":2,"trouble":-2},"outcomes":[{"w":60,"text":"The officer logs it, thanks you, and writes your name in the book. \"Good citizen,\" he says.","tone":"good","effects":[{"t":"street_cred","delta":2},{"t":"needs","delta":{"social":3}}]},{"w":40,"text":"The officer takes forty minutes to find the correct form. You learn many things about the filing system.","tone":"funny","effects":[{"t":"needs","delta":{"stress":3,"energy":-3}}]}]}]$j$::jsonb, 40, 1, 411),
($t$d_yahoo_friend$t$, $t$A "quick business" from Dayo$t$, $t$Your old friend Dayo shows up in a shiny new shirt and a new phone. "My guy, I have a business. You just lend me your account for a little while and I cut you ₦10,000. Easy money." He is smiling too much.$t$, $t$💻$t$, $t$Dayo, an old friend$t$, $t$daily$t$, $j${}$j$::jsonb, $j${"trouble":1,"hustle":0.5}$j$::jsonb, $j$[{"id":"join","label":"Say yes. Money na money","path":{"trouble":5,"hustle":2,"goodwill":-2},"outcomes":[{"w":25,"text":"The money lands. Nothing happens. You feel strangely uneasy, spending it.","tone":"good","effects":[{"t":"cash","amount":6000},{"t":"needs","delta":{"stress":8}},{"t":"path","delta":{"trouble":2}}],"path_w":{"luck":1.5}},{"w":45,"text":"Your account is frozen for \"review\". The bank invites you for a very polite, very long chat. You lose the money you were holding and your peace.","tone":"bad","effects":[{"t":"cash","amount":-5000,"up_to":true},{"t":"needs","delta":{"stress":15}},{"t":"street_cred","delta":-3}],"path_w":{"trouble":1.5}},{"w":30,"text":"Weeks later you hear that Dayo has gone quiet, and a rumour says some of his \"partners\" were picked up. Your phone rings with an unknown number.","tone":"twist","effects":[{"t":"needs","delta":{"stress":10}},{"t":"path","delta":{"luck":-1}},{"t":"follow_up","moment":"c_yahoo_caught","delay_hours":96,"chance":100}],"path_w":{"trouble":1.2}}]},{"id":"refuse","label":"Politely refuse and advise him","path":{"trouble":-3,"goodwill":1},"outcomes":[{"w":55,"text":"He laughs, then goes quiet. \"You are too clean for this city,\" he says, half mocking, half respecting.","tone":"good","effects":[{"t":"needs","delta":{"stress":-2}},{"t":"street_cred","delta":1}]},{"w":45,"text":"He rolls his eyes, but weeks later he remembers your words, and sends you a short message: \"Thanks, my guy.\"","tone":"twist","effects":[{"t":"needs","delta":{"social":4}},{"t":"follow_up","moment":"c_yahoo_caught","delay_hours":168,"chance":60},{"t":"path","delta":{"luck":1}}]}]},{"id":"report","label":"Tell him you will report him","path":{"trouble":-2,"goodwill":-1},"outcomes":[{"w":60,"text":"He storms off angry. A week of cold stares from his friends at the junction follows.","tone":"bad","effects":[{"t":"needs","delta":{"stress":6,"social":-5}}]},{"w":40,"text":"He apologises, laughs, and says he was only testing your character. You are not sure you believe him, but the air clears.","tone":"good","effects":[{"t":"needs","delta":{"stress":-1}}]}]}]$j$::jsonb, 45, 1, 412),
($t$d_stranger_need$t$, $t$A stranger at Ramat Park$t$, $t$A well-dressed woman is standing near the motor park, scrolling her phone with a worried face. "Please, my phone is almost dead and my bag was stolen. I need ₦3,000 to reach Sapele. I will send it back as soon as I get home."$t$, $t$🧳$t$, $t$Ramat Park Junction$t$, $t$daily$t$, $j${"min_cash":3000}$j$::jsonb, $j${"goodwill":0.8}$j$::jsonb, $j$[{"id":"help","label":"Give her ₦3,000","cost":3000,"path":{"goodwill":4},"outcomes":[{"w":45,"text":"She cries, thanks you three times and writes your number. Before she boards she sends you a short blessing.","tone":"good","effects":[{"t":"needs","delta":{"social":5,"stress":-3}}]},{"w":30,"text":"A few days later your phone buzzes: \"It is the lady from Ramat Park. I am safe. Thank you.\" And with it, a transfer.","tone":"twist","effects":[{"t":"needs","delta":{"social":5}},{"t":"follow_up","moment":"c_stranger_repays","delay_hours":72,"chance":100}],"path_w":{"goodwill":1.5,"luck":1}},{"w":25,"text":"Ten minutes later you see her again at the other end of the park, same story, different victim. You laugh, shake your head and learn.","tone":"bad","effects":[{"t":"needs","delta":{"stress":3}},{"t":"path","delta":{"luck":-1}}]}]},{"id":"ticket","label":"Buy her ticket yourself","cost":2500,"path":{"goodwill":3,"trouble":-1},"outcomes":[{"w":70,"text":"You walk her to the ticket counter, pay for the seat, and she is on the bus within ten minutes. No cash in her hand, nothing wasted.","tone":"good","effects":[{"t":"needs","delta":{"social":5}},{"t":"street_cred","delta":1}]},{"w":30,"text":"The conductor sees the whole scene and says, \"Oga, na you be the real hero today.\" The bus passengers clap.","tone":"funny","effects":[{"t":"needs","delta":{"social":6,"fun":4}}]}]},{"id":"decline","label":"Wish her well but pass","path":{"goodwill":-1},"outcomes":[{"w":50,"text":"You tell her you cannot, wish her well and point her to a police post. She nods.","tone":"good","effects":[{"t":"needs","delta":{"stress":2}}]},{"w":50,"text":"She hisses. A nearby vendor says, \"Na so people be now\". The whole afternoon feels slightly colder.","tone":"bad","effects":[{"t":"needs","delta":{"stress":4,"social":-2}}]}]}]$j$::jsonb, 30, 1, 413),
($t$d_job_interview$t$, $t$Interview on Sapele Road$t$, $t$You have an interview this morning at an office on Sapele Road. Your only good shirt is wrinkled, the rain is threatening, and you are not sure the panel will like your answers. A voice in your head says: "Just be yourself." Another says: "Please do not."$t$, $t$💼$t$, $t$Sapele Road$t$, $t$daily$t$, $j${"job":false}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"smart","label":"Iron the shirt and arrive early","cost":1000,"path":{"hustle":2},"outcomes":[{"w":55,"text":"You answer calmly and they smile. The manager says, \"We will call you.\"","tone":"good","effects":[{"t":"needs","delta":{"stress":-4}},{"t":"skill_xp","skill":"charisma","xp":4},{"t":"follow_up","moment":"c_interview_callback","delay_hours":72,"chance":70}],"path_w":{"luck":1}},{"w":25,"text":"The interviewer turns out to be someone from your secondary school. You laugh about old times, and the formal part becomes a chat.","tone":"twist","effects":[{"t":"needs","delta":{"social":5,"stress":-6}},{"t":"path","delta":{"luck":1}},{"t":"follow_up","moment":"c_interview_callback","delay_hours":48,"chance":100}]},{"w":20,"text":"Rain soaks your shirt on the way, and you walk in dripping. You answer well but you feel foolish all day.","tone":"bad","effects":[{"t":"needs","delta":{"stress":6,"hygiene":-6}}]}]},{"id":"casual","label":"Go casual and confident","path":{"hustle":3,"trouble":1},"outcomes":[{"w":35,"text":"Your confidence charms them. One panelist laughs out loud at your joke, and the HR woman writes something with a smile.","tone":"good","effects":[{"t":"needs","delta":{"stress":-4}},{"t":"skill_xp","skill":"charisma","xp":5},{"t":"follow_up","moment":"c_interview_callback","delay_hours":96,"chance":55}]},{"w":65,"text":"The panel is unimpressed by the t-shirt and your joke lands badly. You leave with a polite \"thank you\" and nothing else.","tone":"bad","effects":[{"t":"needs","delta":{"stress":8}}]}]},{"id":"friend","label":"Bring a friend for moral support","path":{"family":1},"outcomes":[{"w":60,"text":"Your friend waits outside and, by accident, ends up charming the receptionist. You get a free cup of tea. The interview is just \"fine\".","tone":"funny","effects":[{"t":"needs","delta":{"social":5,"fun":4}}]},{"w":40,"text":"Having someone at your side calms your nerves. You answer well, and the panel loves your calm.","tone":"good","effects":[{"t":"needs","delta":{"stress":-5}},{"t":"follow_up","moment":"c_interview_callback","delay_hours":120,"chance":50}]}]}]$j$::jsonb, 35, 1, 414),
($t$d_boss_late$t$, $t$Oga wants you to stay late$t$, $t$Five minutes to closing, your boss walks over with a stack of files. "Small thing. I need this done tonight. I will remember you for it." He says "I will remember you" every month, and nothing ever happens.$t$, $t$🧑‍💼$t$, $t$Your boss$t$, $t$daily$t$, $j${"job":true}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"stay","label":"Stay and do it well","path":{"hustle":2,"family":-1},"outcomes":[{"w":45,"text":"You finish at 9 pm, tired but proud. The next morning he praises your work in front of everyone.","tone":"good","effects":[{"t":"needs","delta":{"energy":-12,"stress":4,"social":3}},{"t":"street_cred","delta":1},{"t":"skill_xp","skill":"business","xp":4}],"path_w":{"luck":1}},{"w":40,"text":"You stay late and get a \"thank you\" text at midnight. That is all.","tone":"bad","effects":[{"t":"needs","delta":{"energy":-12,"stress":8}}]},{"w":15,"text":"The files include a client’s complaint nobody wanted to touch. You fix it, and the client sends a thank-you note to the whole office.","tone":"twist","effects":[{"t":"needs","delta":{"energy":-10,"stress":-2}},{"t":"path","delta":{"luck":1}},{"t":"cash","amount":2000}]}]},{"id":"negotiate","label":"Politely ask for something in return","path":{"hustle":3},"outcomes":[{"w":40,"text":"He blinks, then laughs, and promises a day off next week. For once, he actually writes it down.","tone":"good","effects":[{"t":"needs","delta":{"stress":-4}},{"t":"skill_xp","skill":"charisma","xp":3}]},{"w":60,"text":"His smile freezes. \"We will talk,\" he says, in the tone that means \"no\". You do not stay, and the air feels heavy tomorrow.","tone":"bad","effects":[{"t":"needs","delta":{"stress":8}}]}]},{"id":"leave","label":"Say you have family business","path":{"family":3,"hustle":-1},"outcomes":[{"w":60,"text":"You go home, eat with your people and sleep early. Your boss grumbles, but nothing worse happens.","tone":"good","effects":[{"t":"needs","delta":{"social":6,"energy":6,"stress":-6}}]},{"w":40,"text":"He frowns and notes it down. Next week, you get the worst shift. People remember.","tone":"bad","effects":[{"t":"needs","delta":{"stress":5}}]}]}]$j$::jsonb, 30, 1, 415),
($t$d_flood_sapele$t$, $t$Rain on Sapele Road$t$, $t$The rain comes down like it has a grudge. Sapele Road is a brown river and a small car is stuck in the middle with the owner waving for help. Other people watch from dry shelters, wrapped in nylon bags.$t$, $t$🌧️$t$, $t$Sapele Road$t$, $t$daily$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"push","label":"Wade in and help push the car","path":{"goodwill":4,"hustle":1},"outcomes":[{"w":50,"text":"Together with three strangers you get the car out. The driver hugs everyone, soaking wet, and gives each of you a small thank-you.","tone":"good","effects":[{"t":"needs","delta":{"social":7,"hygiene":-12,"energy":-8}},{"t":"cash","amount":1000},{"t":"street_cred","delta":1}]},{"w":30,"text":"As you push, a man from the nearby shop opens his door and offers you all hot pepper soup. You drip on his floor and eat like kings.","tone":"twist","effects":[{"t":"needs","delta":{"social":8,"hunger":18,"fun":6,"hygiene":-10}},{"t":"path","delta":{"luck":1}}],"path_w":{"goodwill":1.2}},{"w":20,"text":"You slip in the water, lose a slipper and bruise your knee. The car gets out. Your pride stays behind.","tone":"bad","effects":[{"t":"needs","delta":{"health":-6,"hygiene":-12,"stress":5}},{"t":"path","delta":{"goodwill":1}}]}]},{"id":"shelter","label":"Wait it out in a nearby buka","cost":700,"path":{"hustle":-1},"outcomes":[{"w":60,"text":"You enjoy hot tea and puff-puff while the rain falls. The street clears an hour later.","tone":"good","effects":[{"t":"needs","delta":{"hunger":10,"stress":-5,"fun":3}}]},{"w":40,"text":"The buka owner tells you every flood story since 1995, with sound effects. You leave knowing too much and feeling warm.","tone":"funny","effects":[{"t":"needs","delta":{"fun":8,"social":4,"hunger":6}}]}]},{"id":"wade","label":"Wade through to get home","path":{"hustle":2},"outcomes":[{"w":55,"text":"You get home soaked, cold and covered in mud. Your socks may never recover.","tone":"bad","effects":[{"t":"needs","delta":{"hygiene":-15,"health":-5,"stress":5}}]},{"w":45,"text":"You lose one slipper in the water, find it again two metres later, and decide it was a very successful journey.","tone":"funny","effects":[{"t":"needs","delta":{"fun":5,"hygiene":-10}}]}]}]$j$::jsonb, 30, 1, 416),
($t$d_viewing_centre$t$, $t$Match night at the viewing centre$t$, $t$It is match night and the small viewing centre in Ugbowo is full. Plastic chairs creak, a generator hums, the screen flickers and every man in the room is a coach. The entry is ₦300. Your favourite team is playing.$t$, $t$⚽$t$, $t$Viewing centre, Ugbowo$t$, $t$daily$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"go","label":"Pay ₦300 and join the noise","cost":300,"path":{"family":-1},"outcomes":[{"w":40,"text":"Your team scores in the last minute and the room explodes. You hug a stranger, and someone buys you a cold drink.","tone":"good","effects":[{"t":"needs","delta":{"fun":20,"social":12,"energy":-5}},{"t":"item","id":"bottled_water","qty":1}]},{"w":35,"text":"Your team loses with a silly own goal. The man behind you blames the referee, the pitch, and \"juju\". You blame the generator.","tone":"bad","effects":[{"t":"needs","delta":{"fun":4,"stress":6,"social":6}}]},{"w":25,"text":"The light goes off during the penalty shootout. The whole room screams for NEPA like a prayer. It works. The light returns and so does the madness.","tone":"funny","effects":[{"t":"needs","delta":{"fun":18,"social":10}}]}]},{"id":"round","label":"Pay for a round of drinks","cost":3000,"path":{"goodwill":3},"outcomes":[{"w":65,"text":"You become a local hero for the night. Chants of your name are heard (well, your nickname).","tone":"good","effects":[{"t":"needs","delta":{"fun":16,"social":16}},{"t":"street_cred","delta":1}]},{"w":35,"text":"The owner of the centre is moved and says: \"Next week you enter free.\" A free pass: not worth much, but you feel respected.","tone":"twist","effects":[{"t":"needs","delta":{"social":10,"fun":10}},{"t":"path","delta":{"luck":1}}]}]},{"id":"home","label":"Stay home and follow the score","path":{"family":1},"outcomes":[{"w":55,"text":"You listen to the match on the radio while your neighbour screams every minute. It is almost the same.","tone":"good","effects":[{"t":"needs","delta":{"fun":6,"stress":-2}}]},{"w":45,"text":"Your phone has no data. You follow the match through shouting from the next compound.","tone":"bad","effects":[{"t":"needs","delta":{"fun":2,"stress":3}}]}]}]$j$::jsonb, 20, 1, 417),
($t$d_juju_rumour$t$, $t$A rumour in the compound$t$, $t$People in the compound whisper that Mama Tina’s sudden good fortune comes from "something strong" she keeps in her room. Nobody has any proof. Everybody has an opinion. Now they are all looking at you for yours.$t$, $t$🔮$t$, $t$The compound$t$, $t$daily$t$, $j${}$j$::jsonb, $j${"faith":0.8}$j$::jsonb, $j$[{"id":"ignore","label":"Say you will not judge anyone","path":{"goodwill":2,"faith":1},"outcomes":[{"w":60,"text":"The whispers lose steam. Mama Tina later thanks you with a small plate of rice and says, \"Not everybody has good manners.\"","tone":"good","effects":[{"t":"needs","delta":{"social":5,"hunger":8}},{"t":"street_cred","delta":1}]},{"w":40,"text":"Someone mutters that you are \"too holy\". You laugh. The gossip moves on to a cat that stole fish.","tone":"funny","effects":[{"t":"needs","delta":{"fun":4}}]}]},{"id":"ask","label":"Ask Mama Tina politely what is going on","path":{"goodwill":1,"hustle":1},"outcomes":[{"w":55,"text":"She laughs till she coughs. Her \"strong thing\" is a new freezer, and she sells ice and cold drinks. She offers you a bottle and a lesson in business.","tone":"twist","effects":[{"t":"needs","delta":{"social":6,"hunger":4}},{"t":"skill_xp","skill":"business","xp":4},{"t":"path","delta":{"luck":1}}]},{"w":45,"text":"She is hurt but glad you asked directly. By evening the rumour has died with a lot of embarrassed faces.","tone":"good","effects":[{"t":"needs","delta":{"social":5,"stress":-3}}]}]},{"id":"gossip","label":"Join the gossip, it is fun","path":{"goodwill":-3,"faith":-1},"outcomes":[{"w":60,"text":"The story grows. By evening Mama Tina has heard your name in it. She does not smile at you anymore.","tone":"bad","effects":[{"t":"needs","delta":{"social":-6,"stress":6}},{"t":"follow_up","moment":"sys_rumour_travels","delay_hours":72,"chance":70}],"path_w":{"goodwill":-1}},{"w":40,"text":"Your version is so dramatic that two people ask if you write movies. Mama Tina is out of town and none the wiser.","tone":"funny","effects":[{"t":"needs","delta":{"fun":6,"social":2}}]}]}]$j$::jsonb, 40, 1, 418),
($t$d_partner_gift$t$, $t$You forgot the date$t$, $t$You are scrolling when it hits you: today is your anniversary with {partner}. You have no gift, no plan and about two hours. The shops will close soon. You can almost hear your own heartbeat.$t$, $t$💐$t$, $t${partner}$t$, $t$daily$t$, $j${"partner":true}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"flowers","label":"Rush to buy flowers and sweets","cost":2500,"path":{"family":2,"goodwill":1},"outcomes":[{"w":60,"text":"{partner} opens the door, sees the flowers and smiles. \"I knew you would remember,\" they say. You do not correct that.","tone":"good","effects":[{"t":"needs","delta":{"social":10,"fun":8,"stress":-6}}]},{"w":40,"text":"The flowers are slightly wilted, but {partner} laughs and says it is the thought that counts. You laugh too.","tone":"funny","effects":[{"t":"needs","delta":{"social":8,"fun":10}}]}]},{"id":"cook","label":"Cook a simple dinner","cost":1200,"path":{"family":3},"outcomes":[{"w":55,"text":"The jollof is a bit burnt at the bottom, but {partner} says it is the best they ever tasted. You believe them, partially.","tone":"good","effects":[{"t":"needs","delta":{"social":10,"fun":10,"hunger":15}},{"t":"skill_xp","skill":"cooking","xp":4}]},{"w":45,"text":"Mid-dinner, {partner} gives you a small card: they planned something too. You share the moment and the burnt rice.","tone":"twist","effects":[{"t":"needs","delta":{"social":12,"fun":12,"hunger":12}},{"t":"path","delta":{"luck":1}}]}]},{"id":"honest","label":"Be honest and promise to make it up","path":{"family":1,"goodwill":1},"outcomes":[{"w":50,"text":"{partner} sighs, then smiles. \"At least you did not lie.\" You plan a better day together next week.","tone":"good","effects":[{"t":"needs","delta":{"social":5,"stress":-2}}]},{"w":50,"text":"{partner} goes quiet. You apologise three times. By night, things are warmer, but you know you owe them.","tone":"bad","effects":[{"t":"needs","delta":{"social":-2,"stress":6}}]}]}]$j$::jsonb, 40, 1, 419),
($t$d_partner_gist$t$, $t$A whisper about {partner}$t$, $t$A friend pulls you aside after church. "I do not want to cause wahala, but I saw {partner} with somebody near Uselu Market, laughing close close." Your stomach twists. You do not know the full story.$t$, $t$🫣$t$, $t$A friend$t$, $t$daily$t$, $j${"partner":true}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"ask","label":"Ask {partner} calmly","path":{"family":2,"goodwill":1},"outcomes":[{"w":55,"text":"It was {partner}’s cousin helping to choose your surprise gift. You feel silly, and {partner} feels loved that you asked.","tone":"twist","effects":[{"t":"needs","delta":{"social":8,"stress":-6}},{"t":"follow_up","moment":"c_partner_surprise","delay_hours":72,"chance":100}],"path_w":{"family":1}},{"w":25,"text":"{partner} admits to something awkward but small. It takes a long talk, but you both come out honest.","tone":"bad","effects":[{"t":"needs","delta":{"social":3,"stress":8}}]},{"w":20,"text":"It was an old friend. {partner} introduces them with a hug, and the whole thing fades.","tone":"good","effects":[{"t":"needs","delta":{"social":5,"stress":-3}}]}]},{"id":"spy","label":"Follow them to see for yourself","path":{"trouble":2,"family":-2},"outcomes":[{"w":60,"text":"You hide behind a pillar in the market, and then {partner} turns and sees you. It is an awkward, loud moment for you both.","tone":"bad","effects":[{"t":"needs","delta":{"stress":14,"social":-8}}]},{"w":40,"text":"You end up following the wrong person for an hour, and buy two bags of onions to look innocent. Your kitchen is now onion-rich.","tone":"funny","effects":[{"t":"needs","delta":{"fun":3,"stress":4}},{"t":"item","id":"onions","qty":2}]}]},{"id":"ignore","label":"Say nothing and think about it","path":{"family":-1},"outcomes":[{"w":55,"text":"The thought sits in your chest for days. You stop sleeping well.","tone":"bad","effects":[{"t":"needs","delta":{"stress":10,"energy":-6}}]},{"w":45,"text":"Without a word, the feeling fades. The next day {partner} calls you \"my favourite person\", and the world resets.","tone":"good","effects":[{"t":"needs","delta":{"social":4,"stress":-3}}]}]}]$j$::jsonb, 50, 1, 420),
($t$d_crush_buka$t$, $t$Someone at the buka$t$, $t$At Mama Osa’s buka a person you have never seen before smiles at you over a plate of rice. You look away, look back, and they are still smiling. A little voice says "Say hello." Another says "Eat your food."$t$, $t$😊$t$, $t$Mama Osa’s buka$t$, $t$daily$t$, $j${"partner":false}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"hello","label":"Say hello and sit with them","path":{"family":1,"hustle":1},"outcomes":[{"w":45,"text":"Conversation flows and you realise you have the same favourite street food. You swap numbers and laugh too loudly.","tone":"good","effects":[{"t":"needs","delta":{"social":10,"fun":8}},{"t":"skill_xp","skill":"charisma","xp":4}]},{"w":35,"text":"You stand up too fast and knock over your drink. They laugh with you, not at you. A decent start.","tone":"funny","effects":[{"t":"needs","delta":{"social":6,"fun":8,"hygiene":-4}}]},{"w":20,"text":"They are already waiting for someone else. You nod, smile and eat your rice very, very slowly.","tone":"bad","effects":[{"t":"needs","delta":{"social":1,"stress":3}}]}]},{"id":"treat","label":"Quietly pay for their meal","cost":1500,"path":{"goodwill":2,"hustle":2},"outcomes":[{"w":50,"text":"They notice at the counter and walk over, grinning. \"Who did this?\" You wave awkwardly. Dinner is on them next time.","tone":"twist","effects":[{"t":"needs","delta":{"social":10,"fun":10}},{"t":"path","delta":{"luck":1}}]},{"w":50,"text":"They send a smile and a thank-you across the room. No more, no less. It is enough.","tone":"good","effects":[{"t":"needs","delta":{"social":5,"fun":5}}]}]},{"id":"eat","label":"Focus on your food","path":{"hustle":-1},"outcomes":[{"w":60,"text":"You finish your rice, feel full and proud of your discipline. The person leaves with someone else.","tone":"good","effects":[{"t":"needs","delta":{"hunger":15,"stress":-2}}]},{"w":40,"text":"You replay it in your head all evening. \"I should have said hello.\" Next time.","tone":"bad","effects":[{"t":"needs","delta":{"hunger":10,"stress":4}}]}]}]$j$::jsonb, 40, 1, 421),
($t$d_kid_homework$t$, $t${child} and the homework$t$, $t${child} puts down a pencil with the face of someone defeated by a worksheet. "I do not understand this one," they say. It is late, you are tired, and the answer is not obvious to you either.$t$, $t$📚$t$, $t${child}$t$, $t$daily$t$, $j${"kids":true}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"sit","label":"Sit down and work through it together","path":{"family":3,"goodwill":1},"outcomes":[{"w":60,"text":"Together you figure it out. {child} beams. \"You are smart,\" they say. You are not, but you let it stand.","tone":"good","effects":[{"t":"needs","delta":{"social":8,"stress":-3,"energy":-5}},{"t":"skill_xp","skill":"teaching","xp":5}]},{"w":40,"text":"You get the answer wrong, then right, then wrong again. {child} laughs so much that homework becomes game night.","tone":"funny","effects":[{"t":"needs","delta":{"social":8,"fun":10,"energy":-5}}]}]},{"id":"tutor","label":"Call a neighbour who is good at it","path":{"family":1,"goodwill":1},"outcomes":[{"w":70,"text":"Your neighbour spends twenty minutes helping and refuses payment. \"Just pay me with your smile,\" she says.","tone":"good","effects":[{"t":"needs","delta":{"social":5,"stress":-2}}]},{"w":30,"text":"Your neighbour also has a younger child, and a new homework group begins. Soon your sitting room is a small school.","tone":"twist","effects":[{"t":"needs","delta":{"social":8}},{"t":"path","delta":{"luck":1}},{"t":"skill_xp","skill":"teaching","xp":4}]}]},{"id":"later","label":"Say you will help tomorrow","path":{"family":-2},"outcomes":[{"w":60,"text":"{child} nods, puts the worksheet away and does not mention it again. That quiet is worse than complaining.","tone":"bad","effects":[{"t":"needs","delta":{"social":-4,"stress":4}}]},{"w":40,"text":"You do help tomorrow, which impresses {child} more than any speech.","tone":"good","effects":[{"t":"needs","delta":{"social":4}}]}]}]$j$::jsonb, 25, 1, 422),
($t$d_kid_toy$t$, $t${child} sees a toy$t$, $t$Passing a shop in Uselu, {child} stops in front of a window and stares at a bright red toy car. They say nothing, which is somehow louder than begging. The price tag says ₦2,500.$t$, $t$🧸$t$, $t${child}$t$, $t$daily$t$, $j${"kids":true,"min_cash":2500}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"buy","label":"Buy it","cost":2500,"path":{"family":3},"outcomes":[{"w":65,"text":"{child} hugs the car and then hugs you. For the next hour you are the best parent in Benin.","tone":"good","effects":[{"t":"needs","delta":{"social":10,"fun":8}}]},{"w":35,"text":"The car breaks in the first ten minutes. {child} is devastated, and you wonder if the toy ever worked.","tone":"bad","effects":[{"t":"needs","delta":{"stress":6,"social":2}}]}]},{"id":"lesson","label":"Explain and promise to save for it","path":{"family":2,"hustle":1},"outcomes":[{"w":50,"text":"{child} listens, thinks and says, \"I will save my pocket money too.\" The seed of a very serious saver is planted.","tone":"twist","effects":[{"t":"needs","delta":{"social":6}},{"t":"path","delta":{"luck":1}}]},{"w":50,"text":"{child} accepts it quietly. Weeks later they remind you gently, and you smile.","tone":"good","effects":[{"t":"needs","delta":{"social":4}}]}]},{"id":"no","label":"Walk on, we are not buying toys today","path":{"family":-1},"outcomes":[{"w":60,"text":"{child} walks silently beside you for the whole street. You feel it more than you expected.","tone":"bad","effects":[{"t":"needs","delta":{"stress":5,"social":-3}}]},{"w":40,"text":"{child} sulks for exactly two minutes and then spots a goat doing something silly. All is forgiven.","tone":"funny","effects":[{"t":"needs","delta":{"fun":4}}]}]}]$j$::jsonb, 25, 1, 423),
($t$d_car_breakdown$t$, $t$Engine trouble on Siluko Road$t$, $t$Your car coughs, shakes and dies on Siluko Road. Steam rises like a village chimney. A man in oily overalls appears out of nowhere. "Oga, I be mechanic. Open am make I look." You have no idea if he is a mechanic.$t$, $t$🚗$t$, $t$Siluko Road$t$, $t$daily$t$, $j${"car":true}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"trust","label":"Let him look","path":{"hustle":1},"outcomes":[{"w":40,"text":"He fixes it in twenty minutes with a bent wire and a lot of confidence. He asks for ₦2,000, and it is worth every kobo.","tone":"good","effects":[{"t":"cash","amount":-2000,"up_to":true},{"t":"skill_xp","skill":"mechanic","xp":5},{"t":"needs","delta":{"stress":-4}}]},{"w":40,"text":"He charges ₦4,000 and finds \"three more problems\". The car runs, but you feel the wallet breathe differently.","tone":"bad","effects":[{"t":"cash","amount":-4000,"up_to":true},{"t":"needs","delta":{"stress":8}}]},{"w":20,"text":"He turns out to be an honest man who runs a small workshop nearby. He gives you his card and a discount for life.","tone":"twist","effects":[{"t":"cash","amount":-1500,"up_to":true},{"t":"skill_xp","skill":"mechanic","xp":4},{"t":"follow_up","moment":"c_car_mechanic","delay_hours":120,"chance":80},{"t":"path","delta":{"luck":1}}]}]},{"id":"tow","label":"Call a tow and a known mechanic","cost":3500,"path":{"hustle":-1,"trouble":-1},"outcomes":[{"w":70,"text":"The tow arrives, the known mechanic is honest, and by evening your car is quiet and working.","tone":"good","effects":[{"t":"needs","delta":{"stress":-3}},{"t":"skill_xp","skill":"mechanic","xp":3}]},{"w":30,"text":"The tow driver sings all the way to the workshop. You arrive with the car repaired and a new favourite song.","tone":"funny","effects":[{"t":"needs","delta":{"fun":6,"stress":-2}}]}]},{"id":"push","label":"Push it to the roadside and wait","path":{"goodwill":1},"outcomes":[{"w":45,"text":"Three strangers help you push. One of them says, \"I once did the same on Airport Road.\" You exchange small kindnesses.","tone":"twist","effects":[{"t":"needs","delta":{"social":6,"energy":-6}},{"t":"path","delta":{"goodwill":1}}]},{"w":55,"text":"You wait two hours in the sun. The car restarts by itself, as if nothing happened. You do not trust it again.","tone":"bad","effects":[{"t":"needs","delta":{"stress":8,"energy":-6}}]}]}]$j$::jsonb, 35, 1, 424),
($t$d_gridlock$t$, $t$Go-slow at Ramat Park$t$, $t$The go-slow at Ramat Park is the stuff of legend today. Cars are packed bumper to bumper, hawkers weave between them selling everything from phone chargers to tiny fans, and a bus conductor is shouting a story that nobody asked for.$t$, $t$🚦$t$, $t$Ramat Park Junction$t$, $t$daily$t$, $j${"car":false}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"wait","label":"Sit tight and endure it","path":{"hustle":-1},"outcomes":[{"w":50,"text":"You use the time to reply messages, drink water and watch the human parade. You arrive late but oddly calm.","tone":"good","effects":[{"t":"needs","delta":{"stress":-2,"fun":3}}]},{"w":50,"text":"A hawker sells you a \"luxury\" mini-fan at a \"special\" price. It works for ten minutes. Still, the memory is priceless.","tone":"funny","effects":[{"t":"cash","amount":-500,"up_to":true},{"t":"needs","delta":{"fun":6}}]}]},{"id":"walk","label":"Get down and walk through","path":{"hustle":1},"outcomes":[{"w":55,"text":"You walk faster than the traffic, enjoy the air and beat the buses to the next junction.","tone":"good","effects":[{"t":"needs","delta":{"health":3,"energy":-6,"stress":-2}},{"t":"skill_xp","skill":"fitness","xp":3}]},{"w":45,"text":"You step in a puddle you did not see, and your shoe makes a very sad sound for the next hour.","tone":"bad","effects":[{"t":"needs","delta":{"hygiene":-8,"stress":4}}]}]},{"id":"chat","label":"Chat with the passenger beside you","path":{"goodwill":1,"family":1},"outcomes":[{"w":45,"text":"He turns out to be a retired lecturer with a thousand stories. You walk away smarter and a little bit lighter.","tone":"twist","effects":[{"t":"needs","delta":{"social":8,"stress":-3}},{"t":"skill_xp","skill":"charisma","xp":3}]},{"w":55,"text":"You swap opinions about traffic, football and rice. By the time the go-slow clears, you are friends.","tone":"good","effects":[{"t":"needs","delta":{"social":7,"fun":4}}]}]}]$j$::jsonb, 25, 1, 425),
($t$d_gang_collection$t$, $t$The gang is collecting$t$, $t$Your boys at the junction are collecting small money for something "important": food for the week, a helmet for a younger member, and a bit for "emergencies". Everybody is looking at you. The contribution is ₦2,000.$t$, $t$🤝$t$, $t$Your gang$t$, $t$daily$t$, $j${"gang":true}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"pay","label":"Pay your share","cost":2000,"path":{"goodwill":2,"trouble":1},"outcomes":[{"w":60,"text":"The money is used well and your name is called with respect at the next meeting.","tone":"good","effects":[{"t":"needs","delta":{"social":8}},{"t":"street_cred","delta":2}]},{"w":40,"text":"The \"emergency\" turns out to be a member’s sick mother. When she recovers, she sends you a thank-you plate of food.","tone":"twist","effects":[{"t":"needs","delta":{"social":9,"hunger":10}},{"t":"path","delta":{"goodwill":1,"luck":1}}]}]},{"id":"half","label":"Pay half and explain","cost":1000,"path":{"hustle":1},"outcomes":[{"w":55,"text":"They nod. It is not perfect, but honesty counts.","tone":"good","effects":[{"t":"needs","delta":{"social":3}}]},{"w":45,"text":"A hard stare from the group leader. \"Half is not full,\" he says. You feel it for the rest of the day.","tone":"bad","effects":[{"t":"needs","delta":{"stress":6,"social":-3}}]}]},{"id":"skip","label":"Make an excuse and leave early","path":{"goodwill":-2,"trouble":1},"outcomes":[{"w":65,"text":"Next time they meet, you are quietly left out of the conversation. Respect is a currency.","tone":"bad","effects":[{"t":"needs","delta":{"social":-6,"stress":6}},{"t":"street_cred","delta":-2}]},{"w":35,"text":"Nobody notices at all, which is both a relief and a little sad.","tone":"good","effects":[{"t":"needs","delta":{"stress":-1}}]}]}]$j$::jsonb, 30, 1, 426),
($t$d_corner_boys$t$, $t$Boys at the junction$t$, $t$A few young men at the junction call you over. "Big man, we have small job. Stand here, look this way, and keep your mouth shut. Nothing dangerous, just business." One of them has a little too much cash and a little too little humility.$t$, $t$😎$t$, $t$Corner boys, Oluku Junction$t$, $t$daily$t$, $j${"gang":false}$j$::jsonb, $j${"trouble":1.2}$j$::jsonb, $j$[{"id":"join","label":"Say yes. It sounds easy","path":{"trouble":5,"hustle":2,"goodwill":-2},"outcomes":[{"w":25,"text":"It is a quiet hour. You are paid ₦4,000 and told to \"forget everything\". You do not feel good about the money.","tone":"good","effects":[{"t":"cash","amount":4000},{"t":"needs","delta":{"stress":10}}],"path_w":{"luck":1.5}},{"w":75,"text":"A patrol arrives and everyone scatters. You are caught with nothing, but you spend two hours answering questions. Your name is on a list now.","tone":"bad","effects":[{"t":"needs","delta":{"stress":15}},{"t":"street_cred","delta":-3},{"t":"path","delta":{"luck":-1}}],"path_w":{"trouble":1.5}}]},{"id":"decline","label":"Decline politely and walk","path":{"trouble":-2,"hustle":-1},"outcomes":[{"w":60,"text":"They shrug. \"Another time.\" You keep walking and breathe once you turn the corner.","tone":"good","effects":[{"t":"needs","delta":{"stress":-2}},{"t":"street_cred","delta":1}]},{"w":40,"text":"One of them shouts \"Respect!\" at your back. You have never been insulted and complimented so fast.","tone":"funny","effects":[{"t":"needs","delta":{"fun":3}}]}]},{"id":"advise","label":"Tell them to go and learn a trade","path":{"goodwill":2,"trouble":-1},"outcomes":[{"w":40,"text":"One of them goes quiet. Weeks later, you see him in a barber’s apron, and he gives you a nod.","tone":"twist","effects":[{"t":"needs","delta":{"social":6}},{"t":"path","delta":{"luck":1}}]},{"w":60,"text":"They laugh at you and the laugh follows you to the next junction.","tone":"bad","effects":[{"t":"needs","delta":{"stress":4,"social":-2}}]}]}]$j$::jsonb, 40, 1, 427),
($t$d_shop_customer$t$, $t$A tough customer$t$, $t$A customer storms into your shop, holding a product and shouting that it "does not work". Other customers are watching. He wants a refund. You are not sure if he is lying, and you cannot afford a bad review.$t$, $t$🛍️$t$, $t$A customer$t$, $t$daily$t$, $j${"business":true}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"refund","label":"Refund him quietly","cost":1500,"path":{"goodwill":2},"outcomes":[{"w":55,"text":"He cools instantly, thanks you and tells three friends that your shop is fair.","tone":"good","effects":[{"t":"needs","delta":{"stress":-3}},{"t":"skill_xp","skill":"business","xp":4}]},{"w":45,"text":"You find out later he did the same at the next shop. At least the crowd saw you were kind.","tone":"bad","effects":[{"t":"needs","delta":{"social":3}}]}]},{"id":"test","label":"Test the product in front of everyone","path":{"hustle":2,"trouble":-1},"outcomes":[{"w":50,"text":"It works perfectly. He mumbles, \"Maybe it was me.\" The crowd claps. You smile and shake hands.","tone":"good","effects":[{"t":"needs","delta":{"social":4}},{"t":"skill_xp","skill":"business","xp":4}]},{"w":50,"text":"It does fail, and the crowd murmurs. You apologise and replace it, and your pride aches.","tone":"bad","effects":[{"t":"needs","delta":{"stress":5}},{"t":"cash","amount":-800,"up_to":true}]}]},{"id":"refuse","label":"Politely refuse. No refunds","path":{"goodwill":-1,"hustle":1},"outcomes":[{"w":65,"text":"He shouts, makes a scene and leaves a bad rating. Your day is long.","tone":"bad","effects":[{"t":"needs","delta":{"stress":8,"social":-3}}]},{"w":35,"text":"He storms off, returns five minutes later with the original receipt, and apologises. Mistakes happen.","tone":"funny","effects":[{"t":"needs","delta":{"stress":2,"fun":2}}]}]}]$j$::jsonb, 25, 1, 428),
($t$d_buka_wallet$t$, $t$Forgot your wallet at the buka$t$, $t$You finish a big plate of rice and meat at Mama Osa’s buka and reach for your wallet. It is not there. Mama Osa looks at you with a calm that is scarier than anger. The bill is ₦2,500.$t$, $t$🍲$t$, $t$Mama Osa’s buka$t$, $t$daily$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"later","label":"Promise to come back and pay tomorrow","path":{"goodwill":1},"outcomes":[{"w":55,"text":"Mama Osa sizes you up, then nods. \"I trust you. Don’t make me regret it.\" You walk out feeling watched by a hundred ancestors.","tone":"good","effects":[{"t":"follow_up","moment":"c_buka_debt","delay_hours":36,"chance":100},{"t":"needs","delta":{"stress":3}}]},{"w":45,"text":"She makes you leave your phone with her as \"security\". You walk home both fed and humbled.","tone":"bad","effects":[{"t":"follow_up","moment":"c_buka_debt","delay_hours":24,"chance":100},{"t":"needs","delta":{"stress":6}}]}]},{"id":"wash","label":"Offer to wash plates to pay","path":{"hustle":2,"goodwill":1},"outcomes":[{"w":55,"text":"An hour of soapy water later, Mama Osa lets you go and gives you free pepper soup. You are tired but honoured.","tone":"good","effects":[{"t":"needs","delta":{"energy":-8,"hygiene":-8,"hunger":6,"social":5}}]},{"w":45,"text":"You break one plate and wash fourteen. Mama Osa says \"balance\" and calls it even. The cook laughs at you for a week.","tone":"funny","effects":[{"t":"needs","delta":{"energy":-8,"fun":5,"social":4}}]}]},{"id":"call","label":"Call a friend to send the money","path":{"family":1},"outcomes":[{"w":60,"text":"Your friend sends it in two minutes and mocks you for ten. You feel very rescued.","tone":"good","effects":[{"t":"needs","delta":{"social":3}},{"t":"cash","amount":-2500,"up_to":true}]},{"w":40,"text":"Your friend does not pick up. Mama Osa taps her ladle. Eventually you work something out, and it costs more than the rice.","tone":"bad","effects":[{"t":"needs","delta":{"stress":8}},{"t":"cash","amount":-3000,"up_to":true}]}]}]$j$::jsonb, 30, 1, 429),
($t$d_checkpoint$t$, $t$A checkpoint on the way$t$, $t$A group of officers has set up a checkpoint on the road ahead. Cars slow down. One of the officers waves you to the side, and you can feel the heartbeat in your throat. In this made-up story, the questions could go either way.$t$, $t$🚓$t$, $t$A checkpoint$t$, $t$daily$t$, $j${}$j$::jsonb, $j${"trouble":1}$j$::jsonb, $j$[{"id":"calm","label":"Cooperate, calm and polite","path":{"trouble":-2,"goodwill":1},"outcomes":[{"w":70,"text":"The officer checks a few things, thanks you for your patience and waves you on. The whole stop lasts three minutes.","tone":"good","effects":[{"t":"needs","delta":{"stress":-3}},{"t":"street_cred","delta":1}]},{"w":30,"text":"The officer smiles. \"People like you make my job easy,\" he says, and gives you a tip about a safer route.","tone":"twist","effects":[{"t":"needs","delta":{"social":4}},{"t":"path","delta":{"luck":1}}]}]},{"id":"talk","label":"Try to talk your way out of it","path":{"hustle":2,"trouble":2},"outcomes":[{"w":30,"text":"Your smooth words work this time. You are waved through, but your pulse stays high for an hour.","tone":"good","effects":[{"t":"needs","delta":{"stress":6}},{"t":"skill_xp","skill":"charisma","xp":4}]},{"w":70,"text":"The officer grows more suspicious the more you talk. The stop lasts forty minutes and your afternoon is gone.","tone":"bad","effects":[{"t":"needs","delta":{"stress":12,"energy":-4}},{"t":"cash","amount":-1500,"up_to":true}],"path_w":{"trouble":1.3}}]},{"id":"turn","label":"Turn around and take another road","path":{"trouble":1,"hustle":1},"outcomes":[{"w":45,"text":"The other road is a dusty wonder full of goats and good gist. You arrive late but entertained.","tone":"funny","effects":[{"t":"needs","delta":{"fun":5,"stress":2}}]},{"w":55,"text":"The other road has potholes the size of small ponds. Your trip takes twice as long.","tone":"bad","effects":[{"t":"needs","delta":{"stress":7,"energy":-4}}]}]}]$j$::jsonb, 35, 1, 430),
($t$d_wifi_joint$t$, $t$Free Wi-Fi at the joint$t$, $t$The Ugbowo Wi-Fi Joint is full of students with laptops. A boy at the next table whispers: "I know one trick to get faster internet for free." You have a deadline, and your data is almost finished.$t$, $t$📶$t$, $t$Ugbowo Wi-Fi Joint$t$, $t$daily$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"pay","label":"Pay for an hour honestly","cost":500,"path":{"trouble":-1,"hustle":1},"outcomes":[{"w":60,"text":"You finish your work and learn two small skills from the tutorial video you open between tasks.","tone":"good","effects":[{"t":"skill_xp","skill":"teaching","xp":4},{"t":"needs","delta":{"stress":-4,"energy":-3}}]},{"w":40,"text":"The boy at the next table was only joking. He ends up being a decent classmate, and you swap contacts.","tone":"twist","effects":[{"t":"needs","delta":{"social":6}},{"t":"path","delta":{"luck":1}}]}]},{"id":"trick","label":"Try the trick","path":{"trouble":3,"hustle":2},"outcomes":[{"w":60,"text":"The trick is a scam. Your account gets locked and you lose your session. You learn a lot about passwords.","tone":"bad","effects":[{"t":"needs","delta":{"stress":8}},{"t":"cash","amount":-1000,"up_to":true}],"path_w":{"trouble":1}},{"w":40,"text":"Whatever it was, it works for an hour. The owner narrows his eyes at you from the counter.","tone":"good","effects":[{"t":"needs","delta":{"stress":5,"fun":3}}]}]},{"id":"data","label":"Buy a small data bundle","cost":700,"path":{"hustle":1},"outcomes":[{"w":100,"text":"You buy a small bundle and finish quietly at home. Sometimes the simple choice is the right one.","tone":"good","effects":[{"t":"needs","delta":{"stress":-3}},{"t":"skill_xp","skill":"teaching","xp":3}]}]}]$j$::jsonb, 25, 1, 431),
($t$d_barber$t$, $t$A new haircut$t$, $t$You walk into Fresh Cut with a half-formed idea of a "fresh, new look". The barber holds up clippers like a sword and asks: "Wetin we dey do today, boss?" The mirror is not very honest.$t$, $t$💈$t$, $t$Fresh Cut Barbing & Salon$t$, $t$daily$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"classic","label":"Your usual, nothing fancy","cost":600,"outcomes":[{"w":70,"text":"Sharp lines, clean neck. You walk out taller than you walked in.","tone":"good","effects":[{"t":"needs","delta":{"hygiene":15,"social":4,"fun":3}}]},{"w":30,"text":"The barber tells stories the whole time. You learn which politician’s cousin owns which shop. Your head is lovely, your ears are full.","tone":"funny","effects":[{"t":"needs","delta":{"hygiene":15,"fun":6}}]}]},{"id":"bold","label":"Try the new style you saw online","cost":1000,"path":{"hustle":2},"outcomes":[{"w":40,"text":"The style is perfect. Everyone on the street looks twice and one stranger asks which shop.","tone":"good","effects":[{"t":"needs","delta":{"hygiene":15,"social":8,"fun":6}},{"t":"skill_xp","skill":"charisma","xp":3}]},{"w":40,"text":"The style is a disaster. You pull a cap on and walk home like a spy.","tone":"bad","effects":[{"t":"needs","delta":{"hygiene":10,"stress":6,"social":-3}}]},{"w":20,"text":"It looks bad, but your cousin says it looks good, then laughs for ten minutes. You laugh too.","tone":"funny","effects":[{"t":"needs","delta":{"hygiene":12,"fun":8}}]}]},{"id":"beard","label":"Just clean up the beard","cost":300,"outcomes":[{"w":100,"text":"A tidy trim, a splash of lotion, and you feel instantly more responsible.","tone":"good","effects":[{"t":"needs","delta":{"hygiene":8,"social":3}}]}]}]$j$::jsonb, 25, 1, 432),
($t$d_ubth_queue$t$, $t$The queue at UBTH$t$, $t$The queue at the teaching hospital is long and hot. Somebody near the front groans and slumps into a chair. People stare, but nobody moves. A nurse is far away at the other end of the corridor.$t$, $t$🏥$t$, $t$UBTH$t$, $t$daily$t$, $j${}$j$::jsonb, $j${"goodwill":0.8}$j$::jsonb, $j$[{"id":"help","label":"Help him and call the nurse","path":{"goodwill":4},"outcomes":[{"w":60,"text":"The nurse arrives quickly. The man recovers and thanks you through shaky breath. The queue claps.","tone":"good","effects":[{"t":"needs","delta":{"social":6,"stress":3}},{"t":"street_cred","delta":2},{"t":"follow_up","moment":"sys_quiet_knock","delay_hours":96,"chance":40}]},{"w":40,"text":"The man turns out to be a retired matron’s husband. She finds you later with a bag of oranges and a hug.","tone":"twist","effects":[{"t":"needs","delta":{"social":8,"hunger":6}},{"t":"path","delta":{"luck":1,"goodwill":1}}]}]},{"id":"water","label":"Offer him water and stay close","cost":200,"path":{"goodwill":2},"outcomes":[{"w":70,"text":"He sips, calms and says he skipped breakfast. You both laugh quietly.","tone":"good","effects":[{"t":"needs","delta":{"social":5}}]},{"w":30,"text":"He sips, burps loudly and everyone laughs, including the nurse. The mood lifts.","tone":"funny","effects":[{"t":"needs","delta":{"social":5,"fun":4}}]}]},{"id":"wait","label":"Keep your place in the line","path":{"goodwill":-1},"outcomes":[{"w":55,"text":"Someone else helps. You feel a small, familiar weight.","tone":"bad","effects":[{"t":"needs","delta":{"stress":4}}]},{"w":45,"text":"The queue moves. You are seen on time and leave with your prescription, a little relieved.","tone":"good","effects":[{"t":"needs","delta":{"stress":-2}}]}]}]$j$::jsonb, 35, 1, 433),
($t$d_igun_street$t$, $t$Bronze on Igun Street$t$, $t$Igun Street rings with hammers. Craftsmen shape bronze the way their fathers did, and a small display of keyrings and plaques sits by the road. An old caster looks up from his work: "Come and see, my friend. Everything here has a story."$t$, $t$🔔$t$, $t$Igun Street$t$, $t$daily$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"buy","label":"Buy a small bronze piece","cost":1500,"path":{"family":1,"goodwill":1},"outcomes":[{"w":65,"text":"You choose a small plaque and he explains what its pattern means. You carry it home like a small treasure.","tone":"good","effects":[{"t":"needs","delta":{"fun":8,"social":4}},{"t":"path","delta":{"faith":1}}]},{"w":35,"text":"He adds a tiny keyring \"for the man who listens\". The whole street smiles at you.","tone":"twist","effects":[{"t":"needs","delta":{"fun":8,"social":6}},{"t":"path","delta":{"luck":1}}]}]},{"id":"watch","label":"Watch him work for a while","path":{"faith":1},"outcomes":[{"w":70,"text":"You stand quietly for an hour, watching heat, hammer and patience. You leave calmer than you came.","tone":"good","effects":[{"t":"needs","delta":{"stress":-8,"fun":5}}]},{"w":30,"text":"He lets you hold a small tool and shows you one careful stroke. You will remember it.","tone":"twist","effects":[{"t":"needs","delta":{"fun":8,"stress":-5}},{"t":"skill_xp","skill":"business","xp":3}]}]},{"id":"photo","label":"Take loud photos and leave","path":{"goodwill":-1},"outcomes":[{"w":55,"text":"The caster looks tired of strangers with phones. You feel the quiet reproach and walk away.","tone":"bad","effects":[{"t":"needs","delta":{"stress":4,"social":-3}}]},{"w":45,"text":"Your photo has your thumb in it, and a goat in the background. Your friends find it hilarious.","tone":"funny","effects":[{"t":"needs","delta":{"fun":5}}]}]}]$j$::jsonb, 40, 1, 434),
($t$d_scam_text$t$, $t$Message from "your bank"$t$, $t$A text arrives: "Dear customer, your account is blocked. Click this link and send your details now to avoid permanent loss." The link looks nothing like your bank. Your phone buzzes with a second message, even more urgent.$t$, $t$✉️$t$, $t$Unknown number$t$, $t$daily$t$, $j${}$j$::jsonb, $j${"trouble":-0.3}$j$::jsonb, $j$[{"id":"delete","label":"Delete and block the number","path":{"trouble":-1,"hustle":-1},"outcomes":[{"w":70,"text":"Clean and simple. You feel quietly smart.","tone":"good","effects":[{"t":"needs","delta":{"stress":-2}},{"t":"street_cred","delta":1}]},{"w":30,"text":"The scammer calls and tries a new accent. You tell him you will pray for him and hang up. Laughter all around.","tone":"funny","effects":[{"t":"needs","delta":{"fun":5}}]}]},{"id":"call","label":"Call your real bank to confirm","path":{"hustle":1},"outcomes":[{"w":60,"text":"The bank confirms it is fake and thanks you for reporting. You feel responsible.","tone":"good","effects":[{"t":"needs","delta":{"stress":-3}},{"t":"skill_xp","skill":"business","xp":3}]},{"w":40,"text":"You spend twenty minutes on hold listening to the same song. The call ends with a cheerful \"no wahala\". Your afternoon is gone.","tone":"bad","effects":[{"t":"needs","delta":{"stress":5,"energy":-3}}]}]},{"id":"click","label":"Click the link","path":{"hustle":1,"trouble":1},"outcomes":[{"w":70,"text":"The page asks for everything. You close it fast, but a small amount is gone from your account.","tone":"bad","effects":[{"t":"cash","amount":-2500,"up_to":true},{"t":"needs","delta":{"stress":10}}],"path_w":{"luck":-1}},{"w":30,"text":"Your phone warns you, \"dangerous site\". You close it in time and swear to be careful.","tone":"good","effects":[{"t":"needs","delta":{"stress":4}}]}]}]$j$::jsonb, 35, 1, 435),
($t$d_elders_greeting$t$, $t$Greeting the elders$t$, $t$At the junction three old men sit under a tree with a draughts board. You know it is polite to greet elders properly. You also know that if you stop, you will be there an hour. One of them already raises his hand.$t$, $t$👴🏽$t$, $t$Old men at the junction$t$, $t$daily$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"greet","label":"Stop, greet properly, sit a little","path":{"goodwill":2,"family":1},"outcomes":[{"w":55,"text":"They bless you and share a story about the old Benin City. One quietly says you were well brought up.","tone":"good","effects":[{"t":"needs","delta":{"social":8,"stress":-3}},{"t":"street_cred","delta":1}]},{"w":45,"text":"One of them is your landlord’s uncle. He mentions your good manners the next time they meet.","tone":"twist","effects":[{"t":"needs","delta":{"social":6}},{"t":"path","delta":{"luck":1}}],"path_w":{"goodwill":1}}]},{"id":"nod","label":"Nod and greet from a distance","path":{"hustle":1},"outcomes":[{"w":60,"text":"They nod back. The day carries on and you arrive on time.","tone":"good","effects":[{"t":"needs","delta":{"social":2}}]},{"w":40,"text":"One of them frowns at the short greeting. You hear a comment about \"these young people\".","tone":"bad","effects":[{"t":"needs","delta":{"stress":3,"social":-2}}]}]},{"id":"game","label":"Challenge one to a game of draughts","path":{"hustle":2,"goodwill":1},"outcomes":[{"w":55,"text":"He beats you in four moves and smiles. Another beats you in three. By the end you are a laughing stock and very happy.","tone":"funny","effects":[{"t":"needs","delta":{"fun":10,"social":8}}]},{"w":45,"text":"You win one game by sheer luck. The old men declare a rematch and treat you like a rival.","tone":"good","effects":[{"t":"needs","delta":{"fun":10,"social":8}},{"t":"street_cred","delta":1}],"path_w":{"luck":1}}]}]$j$::jsonb, 25, 1, 436),
($t$d_suya_man$t$, $t$The suya man$t$, $t$The smell of suya on Ring Road is unfair. The suya man is slicing meat with the speed of a chef and the confidence of a king. The queue is long. Your wallet whispers "no". Your stomach shouts "yes".$t$, $t$🍢$t$, $t$Suya stand, Ring Road$t$, $t$daily$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"buy","label":"Buy one stick and wait","cost":600,"outcomes":[{"w":60,"text":"Hot, spicy and perfect. You finish it in four bites and consider a second one.","tone":"good","effects":[{"t":"needs","delta":{"hunger":18,"fun":6}},{"t":"item","id":"suya_stick","qty":1}]},{"w":40,"text":"The suya man adds an extra piece and a wink: \"For people who wait nicely.\" The queue grumbles, the day brightens.","tone":"twist","effects":[{"t":"needs","delta":{"hunger":22,"fun":8,"social":3}},{"t":"path","delta":{"luck":1}}]}]},{"id":"tip","label":"Buy for you and a hungry child nearby","cost":1200,"path":{"goodwill":3},"outcomes":[{"w":70,"text":"The child’s eyes light up. The mother thanks you shyly. The suya man waves a free pepper sachet at you.","tone":"good","effects":[{"t":"needs","delta":{"hunger":14,"social":6}}]},{"w":30,"text":"The suya man refuses your money for the second stick. \"That one is for the child,\" he says. Kindness spreads.","tone":"twist","effects":[{"t":"needs","delta":{"hunger":14,"social":8}},{"t":"path","delta":{"luck":1}}]}]},{"id":"skip","label":"Resist and walk on","path":{"hustle":1},"outcomes":[{"w":50,"text":"You keep your money. The smell follows you for three streets.","tone":"good","effects":[{"t":"needs","delta":{"stress":1}}]},{"w":50,"text":"You walk three steps and turn right back. The suya wins. It always wins.","tone":"funny","effects":[{"t":"cash","amount":-600,"up_to":true},{"t":"needs","delta":{"hunger":15,"fun":6}}]}]}]$j$::jsonb, 20, 1, 437),
($t$d_noisy_neighbour$t$, $t$Music at midnight$t$, $t$Midnight. Somebody in the next compound is playing music like the speaker owes them money. The bass shakes your walls. You have an early start tomorrow and a very short patience.$t$, $t$🔊$t$, $t$The next compound$t$, $t$daily$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"knock","label":"Walk over and ask politely","path":{"goodwill":1},"outcomes":[{"w":55,"text":"The neighbour turns it down, apologises and offers you a bottle of zobo. You both laugh about the volume.","tone":"good","effects":[{"t":"needs","delta":{"social":5,"stress":-4}},{"t":"item","id":"zobo","qty":1}]},{"w":45,"text":"He turns it down for ten minutes, then raises it again. You return to bed with a sigh and a pillow over your head.","tone":"bad","effects":[{"t":"needs","delta":{"stress":8,"energy":-6}}]}]},{"id":"join","label":"Join the party","path":{"goodwill":1,"family":-1},"outcomes":[{"w":60,"text":"It is somebody’s birthday. You dance badly, eat cake and sleep three hours. Totally worth it.","tone":"funny","effects":[{"t":"needs","delta":{"fun":14,"social":10,"energy":-10}}]},{"w":40,"text":"The party is full of strangers and arguments. You leave at 2 am, annoyed and sleepy.","tone":"bad","effects":[{"t":"needs","delta":{"social":3,"energy":-10,"stress":6}}]}]},{"id":"endure","label":"Put on earplugs and endure","path":{"hustle":-1},"outcomes":[{"w":50,"text":"Earplugs and a fan do wonders. You sleep. Sort of.","tone":"good","effects":[{"t":"needs","delta":{"energy":4,"stress":2}}]},{"w":50,"text":"Bass travels through earplugs, walls and dreams. You get up with the face of someone who fought a lion.","tone":"bad","effects":[{"t":"needs","delta":{"energy":-8,"stress":8}}]}]}]$j$::jsonb, 25, 1, 438),
($t$d_borehole$t$, $t$The borehole is dry$t$, $t$The borehole that serves the whole street gives out a long, sad cough and then nothing. Women with buckets begin to gather and an argument starts about who is to blame. You have some water stored at home.$t$, $t$🚰$t$, $t$Your street$t$, $t$daily$t$, $j${}$j$::jsonb, $j${"goodwill":0.8}$j$::jsonb, $j$[{"id":"share","label":"Share your stored water","cost":300,"path":{"goodwill":4,"family":1},"outcomes":[{"w":60,"text":"You fill buckets until your tank is nearly empty. By evening, the street remembers who helped.","tone":"good","effects":[{"t":"needs","delta":{"social":8,"energy":-5}},{"t":"street_cred","delta":1},{"t":"follow_up","moment":"sys_kind_word","delay_hours":72,"chance":50}]},{"w":40,"text":"The next morning, a neighbour leaves a full bucket at your door, with a note: \"From all of us.\"","tone":"twist","effects":[{"t":"needs","delta":{"social":8,"stress":-4}},{"t":"path","delta":{"luck":1}}],"path_w":{"goodwill":1.5}}]},{"id":"organise","label":"Organise a contribution to repair it","cost":1000,"path":{"goodwill":2,"hustle":2},"outcomes":[{"w":55,"text":"You collect ₦20,000 from fourteen households, and the mechanic fixes it by evening. Your name is on the street group chat for a whole day.","tone":"good","effects":[{"t":"needs","delta":{"social":8}},{"t":"skill_xp","skill":"business","xp":4},{"t":"follow_up","moment":"sys_kind_word","delay_hours":48,"chance":60}]},{"w":45,"text":"Half the people promise and do not pay. The repair is late. You get tired of explaining.","tone":"bad","effects":[{"t":"needs","delta":{"stress":8,"social":2}}]}]},{"id":"keep","label":"Keep your water for yourself","path":{"goodwill":-3,"family":-1},"outcomes":[{"w":65,"text":"A neighbour sees you carrying a bucket and says nothing. It is worse than if she did.","tone":"bad","effects":[{"t":"needs","delta":{"stress":5,"social":-5}}]},{"w":35,"text":"You stay inside, drink cold water and do not feel guilty until much later.","tone":"good","effects":[{"t":"needs","delta":{"stress":-1}}]}]}]$j$::jsonb, 40, 1, 439),
($t$d_goat_compound$t$, $t$A goat in the compound$t$, $t$You come home to find a goat in your compound, calmly eating your landlord’s flowers. Nobody claims it. The goat locks eyes with you, chewing slowly. It looks like it pays rent.$t$, $t$🐐$t$, $t$Your compound$t$, $t$daily$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"drive","label":"Drive it out of the compound","path":{"hustle":1},"outcomes":[{"w":60,"text":"You chase it twice around the compound while the neighbours cheer. It leaves with dignity. You leave with a cramp.","tone":"funny","effects":[{"t":"needs","delta":{"fun":10,"energy":-6,"social":4}}]},{"w":40,"text":"The goat leaves, but takes your clothesline with it. You spend an hour untangling everything.","tone":"bad","effects":[{"t":"needs","delta":{"stress":5,"energy":-4}}]}]},{"id":"find","label":"Ask around for the owner","path":{"goodwill":2},"outcomes":[{"w":60,"text":"The owner is a child from two streets away who has been looking for it all day. He is so happy that he cries.","tone":"good","effects":[{"t":"needs","delta":{"social":8,"fun":4}},{"t":"street_cred","delta":1},{"t":"follow_up","moment":"sys_quiet_knock","delay_hours":60,"chance":60}]},{"w":40,"text":"The owner is an old man, who thanks you with a small bag of groundnuts and a story that lasts forty minutes.","tone":"twist","effects":[{"t":"needs","delta":{"social":7,"hunger":6}},{"t":"item","id":"boli_groundnut","qty":1},{"t":"path","delta":{"luck":1}}]}]},{"id":"leave","label":"Leave it. It is not your goat","path":{"goodwill":-1},"outcomes":[{"w":70,"text":"The goat finishes the flowers, then naps under your window. You are now the keeper of a goat.","tone":"funny","effects":[{"t":"needs","delta":{"fun":5}}]},{"w":30,"text":"The landlord blames you for the flowers. You protest. The goat says nothing.","tone":"bad","effects":[{"t":"needs","delta":{"stress":6}},{"t":"cash","amount":-500,"up_to":true}]}]}]$j$::jsonb, 40, 1, 440),
($t$d_lost_child$t$, $t$A child in Oba Market$t$, $t$Amid the noise of Oba Market you notice a small girl standing still near a pepper stall, clutching a plastic bag. Her eyes are wet. People rush past her. She looks at you and whispers, "I cannot find my mama."$t$, $t$👦🏽$t$, $t$Oba Market$t$, $t$daily$t$, $j${}$j$::jsonb, $j${"goodwill":0.8}$j$::jsonb, $j$[{"id":"stay","label":"Stay with her and find her mother","path":{"goodwill":4,"family":1},"outcomes":[{"w":55,"text":"You walk the market asking until a woman in a red wrapper runs toward you, crying. The reunion is loud, happy and emotional.","tone":"good","effects":[{"t":"needs","delta":{"social":8,"energy":-6}},{"t":"street_cred","delta":2}]},{"w":45,"text":"The mother is a big aunty from Uselu who runs three stalls. She promises you a very special favour next time you visit.","tone":"twist","effects":[{"t":"needs","delta":{"social":8,"stress":-3}},{"t":"path","delta":{"luck":1}},{"t":"follow_up","moment":"c_lost_child_aunty","delay_hours":96,"chance":85}],"path_w":{"goodwill":1.5}}]},{"id":"security","label":"Take her to the market security","path":{"goodwill":2,"trouble":-1},"outcomes":[{"w":70,"text":"The security announces her name on the loudspeaker. A mother appears within ten minutes.","tone":"good","effects":[{"t":"needs","delta":{"social":5}},{"t":"street_cred","delta":1}]},{"w":30,"text":"The loudspeaker squeals and the whole market laughs. The girl cheers up and the mother arrives, embarrassed and relieved.","tone":"funny","effects":[{"t":"needs","delta":{"social":5,"fun":4}}]}]},{"id":"walk","label":"Tell a vendor and continue","path":{"goodwill":-1},"outcomes":[{"w":55,"text":"Guilt follows you. Later you hear it all ended well, but you wish you had stayed.","tone":"bad","effects":[{"t":"needs","delta":{"stress":5}}]},{"w":45,"text":"The vendor takes charge and the girl is soon reunited. You exhale, relieved.","tone":"good","effects":[{"t":"needs","delta":{"stress":-1}}]}]}]$j$::jsonb, 45, 1, 441),
($t$d_airport_parcel$t$, $t$A parcel for a friend$t$, $t$Near Benin Airport a smartly dressed man smiles at you: "Please, can you carry this small parcel for my brother in Asaba? He is waiting. It is only clothes." The parcel is sealed. The man is too friendly.$t$, $t$📦$t$, $t$Benin Airport$t$, $t$daily$t$, $j${}$j$::jsonb, $j${"trouble":1}$j$::jsonb, $j$[{"id":"refuse","label":"Politely refuse","path":{"trouble":-3,"goodwill":-1},"outcomes":[{"w":75,"text":"His smile drops, then returns. \"No problem.\" You walk on, your heart quiet. Never carry what you did not pack.","tone":"good","effects":[{"t":"needs","delta":{"stress":-3}},{"t":"street_cred","delta":1}]},{"w":25,"text":"He offers it to the next person, who also refuses. You both give each other a small nod, as if you were colleagues.","tone":"funny","effects":[{"t":"needs","delta":{"fun":3}}]}]},{"id":"open","label":"Ask to see what is inside","path":{"hustle":1,"trouble":-1},"outcomes":[{"w":55,"text":"He hesitates a second too long, then hurries away. You report it to a security guard, who thanks you and writes your name down.","tone":"twist","effects":[{"t":"street_cred","delta":2},{"t":"needs","delta":{"stress":4}},{"t":"path","delta":{"luck":1}}]},{"w":45,"text":"It is genuinely clothes. A little embarrassed, you apologise. He laughs and says he understands, and you do carry it.","tone":"good","effects":[{"t":"needs","delta":{"social":4}}]}]},{"id":"take","label":"Take it, he looks respectable","path":{"trouble":4,"hustle":1},"outcomes":[{"w":70,"text":"At the check, the parcel raises questions you cannot answer. You spend a long, scary afternoon, and your name goes on a list.","tone":"bad","effects":[{"t":"needs","delta":{"stress":18}},{"t":"street_cred","delta":-3},{"t":"cash","amount":-3000,"up_to":true}],"path_w":{"trouble":1.5}},{"w":30,"text":"Nothing happens and you are paid ₦2,000, but for days you feel something heavy in your chest.","tone":"good","effects":[{"t":"cash","amount":2000},{"t":"needs","delta":{"stress":10}}]}]}]$j$::jsonb, 40, 1, 442),
($t$d_pos_stand$t$, $t$No network at the PoS stand$t$, $t$You need ₦10,000 in cash and the PoS stand on Sapele Road is the only one open. The attendant frowns at her machine: "Network is bad, my dear. Wait small." Behind you, a woman clears her throat meaningfully.$t$, $t$🏧$t$, $t$Sapele Road PoS Stand$t$, $t$daily$t$, $j${"min_cash":3000}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"wait","label":"Wait patiently","path":{"goodwill":1},"outcomes":[{"w":55,"text":"After ten minutes the network wakes up. She counts out your cash and wishes you a good day.","tone":"good","effects":[{"t":"needs","delta":{"stress":-1}}]},{"w":45,"text":"During the wait, you learn about the attendant’s five cousins, her business plan and her favourite music. The cash is almost an afterthought.","tone":"funny","effects":[{"t":"needs","delta":{"social":5,"fun":3}}]}]},{"id":"another","label":"Try another stand down the road","path":{"hustle":2},"outcomes":[{"w":45,"text":"The next stand is quick and polite. You are done in three minutes.","tone":"good","effects":[{"t":"needs","delta":{"stress":-2}}]},{"w":55,"text":"The next stand has a longer queue and a higher fee. You shake your head and pay.","tone":"bad","effects":[{"t":"cash","amount":-300,"up_to":true},{"t":"needs","delta":{"stress":5}}]}]},{"id":"help","label":"Offer to help the woman behind you first","path":{"goodwill":3},"outcomes":[{"w":50,"text":"She turns out to be a trader in a hurry. She presses ₦500 into your palm: \"For being human.\"","tone":"twist","effects":[{"t":"cash","amount":500},{"t":"needs","delta":{"social":6}},{"t":"path","delta":{"luck":1}}]},{"w":50,"text":"She thanks you quickly and runs. Small act, light heart.","tone":"good","effects":[{"t":"needs","delta":{"social":4}}]}]}]$j$::jsonb, 25, 1, 443),
($t$c_boy_bank$t$, $t$The boy from Ring Road$t$, $t$A young man in a neat suit stops you outside a bank in GRA. "Sir? Ring Road, the sachet water, the fallen tray?" It is the boy, years older somehow, now an assistant manager. "I was always going to find you," he says. "Please, come inside."$t$, $t$🏦$t$, $t$A smart young man$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"go","label":"Go in with him","path":{"goodwill":1},"outcomes":[{"w":60,"text":"He pulls out a chair, opens a small account for you and says, \"Small thanks, big heart.\" There is ₦6,000 in it already.","tone":"good","effects":[{"t":"cash","amount":6000},{"t":"needs","delta":{"social":8,"stress":-5}},{"t":"skill_xp","skill":"business","xp":5}]},{"w":40,"text":"He offers you tea, a friendly chat about saving and a small gift to start a savings habit. You leave with a lot more than cash.","tone":"twist","effects":[{"t":"cash","amount":3500},{"t":"needs","delta":{"social":8}},{"t":"skill_xp","skill":"business","xp":7},{"t":"path","delta":{"luck":1}}]}]},{"id":"humble","label":"Say it was nothing","path":{"goodwill":2,"faith":1},"outcomes":[{"w":70,"text":"He insists anyway, and writes his number on a card. \"Anytime,\" he says. You walk away glowing.","tone":"good","effects":[{"t":"cash","amount":2000},{"t":"needs","delta":{"social":6,"stress":-4}}]},{"w":30,"text":"He smiles, nods, and introduces you to his manager as \"the man who taught me kindness\". That is better than money.","tone":"twist","effects":[{"t":"needs","delta":{"social":10}},{"t":"street_cred","delta":2}]}]}]$j$::jsonb, 0, 0, 444),
($t$c_phone_police$t$, $t$Knock at the door$t$, $t$Two officers stand at your door holding a notebook. "Good afternoon. A phone matching this serial number was reported stolen at New Benin Market. We understand you may have it." The phone in your pocket suddenly feels very heavy.$t$, $t$🚔$t$, $t$Two officers$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"truth","label":"Tell the truth and hand it over","path":{"trouble":-3,"goodwill":1},"outcomes":[{"w":60,"text":"They note your story, check the phone and thank you for cooperating. You lose the phone but keep your name.","tone":"good","effects":[{"t":"needs","delta":{"stress":-4}},{"t":"street_cred","delta":1}]},{"w":40,"text":"You are asked to describe the seller. Your description helps them catch the actual thief a week later. The officer shakes your hand.","tone":"twist","effects":[{"t":"needs","delta":{"stress":-2}},{"t":"street_cred","delta":3},{"t":"path","delta":{"luck":1}}]}]},{"id":"lie","label":"Say you do not know what they mean","path":{"trouble":4,"goodwill":-1},"outcomes":[{"w":75,"text":"They look at the phone on the table and at you. The next hour is long. You lose the phone, ₦3,000 in \"fees\" and some respect.","tone":"bad","effects":[{"t":"cash","amount":-3000,"up_to":true},{"t":"needs","delta":{"stress":14}},{"t":"street_cred","delta":-3}],"path_w":{"trouble":1.2}},{"w":25,"text":"They accept your story, take the phone and leave. You are fine, but the fear sits with you for days.","tone":"good","effects":[{"t":"needs","delta":{"stress":8}}]}]},{"id":"lawyer","label":"Ask to call a lawyer friend first","cost":2000,"path":{"hustle":1},"outcomes":[{"w":60,"text":"Your friend arrives, explains things calmly and the matter is settled with a short statement.","tone":"good","effects":[{"t":"needs","delta":{"stress":-2}}]},{"w":40,"text":"The officers wait while your friend gets stuck in traffic for an hour. The tension grows, and the outcome is the same.","tone":"bad","effects":[{"t":"needs","delta":{"stress":8}}]}]}]$j$::jsonb, 0, 0, 445),
($t$c_keke_thanks$t$, $t$The keke driver remembers$t$, $t$A keke slows beside you and the driver leans out, grinning. "Oga! Na you be the one wey help me!" It is the keke driver. He insists on carrying you for free today, and he has a lot of gist about how the week went.$t$, $t$🛺$t$, $t$Keke driver$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"ride","label":"Accept the free ride","path":{"goodwill":1},"outcomes":[{"w":65,"text":"He takes the scenic route, tells you three stories and drops you with a handshake. You keep the fare in your pocket.","tone":"good","effects":[{"t":"needs","delta":{"social":6,"fun":5}},{"t":"cash","amount":800}]},{"w":35,"text":"He introduces you to the other keke drivers at the junction. Now half the junction waves when you pass. Very handy.","tone":"twist","effects":[{"t":"needs","delta":{"social":9}},{"t":"path","delta":{"luck":1}},{"t":"street_cred","delta":1}]}]},{"id":"pay","label":"Insist on paying anyway","cost":300,"path":{"goodwill":2},"outcomes":[{"w":100,"text":"He argues but accepts. \"You be good person,\" he says, and you ride off with a warm feeling.","tone":"good","effects":[{"t":"needs","delta":{"social":5,"stress":-3}}]}]}]$j$::jsonb, 0, 0, 446),
($t$c_neighbour_repays$t$, $t$Mr. Osaze at the door$t$, $t$Mr. Osaze knocks, holding a steaming pot wrapped in a cloth. "Egusi and pounded yam," he says. "You helped me when the light went. In this compound, we remember." His wife is behind him, smiling.$t$, $t$🍲$t$, $t$Mr. Osaze, next door$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"accept","label":"Accept with thanks","path":{"goodwill":1,"family":1},"outcomes":[{"w":70,"text":"The food is delicious. The conversation is warmer. You sleep well that night.","tone":"good","effects":[{"t":"needs","delta":{"hunger":25,"social":8,"stress":-4}}]},{"w":30,"text":"Mr. Osaze also hands you a spare torch light \"for the next time\". The compound smiles about it for a week.","tone":"twist","effects":[{"t":"needs","delta":{"hunger":22,"social":10}},{"t":"item","id":"bottled_water","qty":1},{"t":"path","delta":{"luck":1}}]}]},{"id":"share","label":"Say let us eat together","path":{"goodwill":2,"family":2},"outcomes":[{"w":100,"text":"You eat together on the compound step. Neighbours drift in with plates and stools. It becomes a little street party.","tone":"good","effects":[{"t":"needs","delta":{"hunger":22,"social":14,"fun":8}}]}]}]$j$::jsonb, 0, 0, 447),
($t$c_exam_warning$t$, $t$A letter from the lecturer$t$, $t$A letter is pinned in your pigeonhole: "Please see the lecturer in the department office." You remember the exam and the paper in your hand outside the hall. Your legs feel less sure than usual.$t$, $t$📄$t$, $t$UNIBEN, Ugbowo Campus$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"honest","label":"Go in and be honest","path":{"trouble":-3,"goodwill":1},"outcomes":[{"w":60,"text":"The lecturer listens, sighs and says: \"Honesty is better than any paper.\" You get a written warning and a second chance.","tone":"good","effects":[{"t":"needs","delta":{"stress":-4}},{"t":"street_cred","delta":1}]},{"w":40,"text":"The lecturer is stern. You repeat the paper and lose a bit of your reputation, but you keep your dignity.","tone":"bad","effects":[{"t":"needs","delta":{"stress":8}},{"t":"street_cred","delta":-1}]}]},{"id":"deny","label":"Deny everything","path":{"trouble":3,"goodwill":-2},"outcomes":[{"w":80,"text":"She has the paper. The meeting is brief, cold and costly. Your name goes on a \"watch\" list.","tone":"bad","effects":[{"t":"needs","delta":{"stress":14}},{"t":"street_cred","delta":-3}],"path_w":{"trouble":1.2}},{"w":20,"text":"She lets it go this time, but her eyes follow you for the rest of the semester.","tone":"good","effects":[{"t":"needs","delta":{"stress":8}}]}]}]$j$::jsonb, 0, 0, 448),
($t$c_owambe_contact$t$, $t$The man from the high table$t$, $t$Your phone rings with an unknown number. "Good afternoon, we met at Madam Ivie’s owambe. I run a few shops in Oregbeni. I may need someone reliable for a small job. Are you free this week?"$t$, $t$📱$t$, $t$A new contact$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"yes","label":"Say yes and meet him","path":{"hustle":2},"outcomes":[{"w":55,"text":"He gives you a small job: a delivery list and a few phone calls. He pays ₦3,000 and promises more if you do well.","tone":"good","effects":[{"t":"cash","amount":3000},{"t":"skill_xp","skill":"business","xp":5},{"t":"needs","delta":{"energy":-6}}]},{"w":45,"text":"It turns out to be more tiring than rewarding. He pays ₦1,000 and says \"we will see\".","tone":"bad","effects":[{"t":"cash","amount":1000},{"t":"needs","delta":{"energy":-8,"stress":4}}]}]},{"id":"later","label":"Say you will call back next week","path":{"hustle":-1},"outcomes":[{"w":55,"text":"You forget, and he finds someone else. Life goes on.","tone":"bad","effects":[{"t":"needs","delta":{"stress":2}}]},{"w":45,"text":"You call back, he is still interested and the deal is a little better.","tone":"good","effects":[{"t":"needs","delta":{"social":4}}]}]}]$j$::jsonb, 0, 0, 449),
($t$c_wallet_owner$t$, $t$The retired teacher calls$t$, $t$Your phone rings. "Hello, it is Mr. Aigbe. The man with the wallet. I thought of you today. My grandson needs help with his maths and I thought: that honest young person might be a good example. Could you spare an hour?"$t$, $t$👨🏽‍🏫$t$, $t$Mr. Aigbe, a retired teacher$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"help","label":"Spend an hour with his grandson","path":{"goodwill":2,"family":1},"outcomes":[{"w":65,"text":"You explain fractions with groundnuts. The boy laughs and understands. Mr. Aigbe presses ₦2,000 and a tin of biscuits into your hands.","tone":"good","effects":[{"t":"cash","amount":2000},{"t":"needs","delta":{"social":8}},{"t":"skill_xp","skill":"teaching","xp":6}]},{"w":35,"text":"Mr. Aigbe introduces you to the school director, who is looking for a part-time helper. The seed of a new chapter.","tone":"twist","effects":[{"t":"needs","delta":{"social":8}},{"t":"skill_xp","skill":"teaching","xp":6},{"t":"path","delta":{"luck":1,"hustle":1}}]}]},{"id":"thanks","label":"Thank him, but say you are busy","path":{"family":-1},"outcomes":[{"w":60,"text":"He understands and says the door is open. A warm, open door is a good thing to have.","tone":"good","effects":[{"t":"needs","delta":{"social":3}}]},{"w":40,"text":"He sighs and says goodbye, sounding a little lonelier than before.","tone":"bad","effects":[{"t":"needs","delta":{"stress":4}}]}]}]$j$::jsonb, 0, 0, 450),
($t$c_yahoo_caught$t$, $t$News about Dayo$t$, $t$A message arrives from a number you do not know: "Dayo has been picked up. They are going through his contacts. Please call me." The words sit like hot coals. It could be a friend. It could be a trap.$t$, $t$📰$t$, $t$A message$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"call","label":"Call the number back","path":{"goodwill":1},"outcomes":[{"w":50,"text":"It is Dayo’s sister. She is terrified. You tell her what you know and recommend a lawyer. She thanks you through tears.","tone":"good","effects":[{"t":"needs","delta":{"social":5,"stress":6}},{"t":"street_cred","delta":1}]},{"w":50,"text":"Nobody picks up. The silence is worse than any answer.","tone":"bad","effects":[{"t":"needs","delta":{"stress":10}}]}]},{"id":"lowlow","label":"Stay quiet and keep a low profile","path":{"trouble":1,"hustle":-1},"outcomes":[{"w":55,"text":"Nothing happens. Days pass. You breathe again, but you will think twice about old friends.","tone":"good","effects":[{"t":"needs","delta":{"stress":4}}]},{"w":45,"text":"Two days later an officer politely asks to \"have a chat\". It turns out to be a long afternoon, but nothing more.","tone":"bad","effects":[{"t":"needs","delta":{"stress":12}},{"t":"cash","amount":-1000,"up_to":true}],"path_w":{"trouble":1.2}}]}]$j$::jsonb, 0, 0, 451),
($t$c_stranger_repays$t$, $t$The lady from Ramat Park$t$, $t$A message arrives: "Hello, it is the lady you helped at Ramat Park. I reached Sapele safely, thanks to you. I have sent what I promised. Please accept it with my thanks." A transfer notification follows.$t$, $t$💌$t$, $t$A message from the lady$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"thanks","label":"Reply with warm thanks","path":{"goodwill":1},"outcomes":[{"w":65,"text":"She sends back ₦3,500 and a prayer. You did not lose; you gained a kind friend.","tone":"good","effects":[{"t":"cash","amount":3500},{"t":"needs","delta":{"social":6}}]},{"w":35,"text":"She sends ₦3,000 and adds that she runs a small boutique in Sapele. \"Come visit,\" she says. A door opens somewhere.","tone":"twist","effects":[{"t":"cash","amount":3000},{"t":"needs","delta":{"social":8}},{"t":"path","delta":{"luck":1}}]}]},{"id":"refuse","label":"Tell her to keep it","path":{"goodwill":3,"faith":1},"outcomes":[{"w":60,"text":"She insists, you insist back, and eventually she sends it anyway with a warm voice note.","tone":"good","effects":[{"t":"cash","amount":3000},{"t":"needs","delta":{"social":6}}]},{"w":40,"text":"She sends a heartfelt prayer instead. You spend the day feeling lighter than you can explain.","tone":"twist","effects":[{"t":"needs","delta":{"social":10,"stress":-8}},{"t":"path","delta":{"luck":2}}]}]}]$j$::jsonb, 0, 0, 452),
($t$c_interview_callback$t$, $t$They called back$t$, $t$A call. "Good afternoon, we are calling from the office on Sapele Road. We would like you to come in tomorrow for a short second meeting." Your heart does a small dance. They do not say whether it is good news.$t$, $t$📞$t$, $t$The office on Sapele Road$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"prep","label":"Prepare properly tonight","path":{"hustle":2},"outcomes":[{"w":55,"text":"You rehearse, sleep and show up fresh. The panel nods more than they speak. A good sign.","tone":"good","effects":[{"t":"needs","delta":{"stress":-3}},{"t":"skill_xp","skill":"charisma","xp":5},{"t":"cash","amount":2000}]},{"w":45,"text":"You study too hard, sleep too little and stumble over a simple question. They are still kind, but the room feels cooler.","tone":"bad","effects":[{"t":"needs","delta":{"stress":8,"energy":-8}}]}]},{"id":"wing","label":"Wing it. You did well last time","path":{"hustle":3,"trouble":1},"outcomes":[{"w":35,"text":"Your confidence charms them and they smile. They say they will decide by Friday.","tone":"good","effects":[{"t":"needs","delta":{"stress":-2}},{"t":"skill_xp","skill":"charisma","xp":4}]},{"w":65,"text":"They ask three questions you did not expect. You answer with the confidence of someone who did not read the question.","tone":"bad","effects":[{"t":"needs","delta":{"stress":10}}]}]}]$j$::jsonb, 0, 0, 453),
($t$c_partner_surprise$t$, $t$The surprise$t$, $t${partner} greets you with a suspiciously bright smile. "Come with me. Close your eyes." You are led, step by step, to a little table with a candle, a plate of your favourite food and, yes, the gift your friend’s whisper had been all about.$t$, $t$🎁$t$, $t${partner}$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"thank","label":"Hug {partner} and thank them","path":{"family":3},"outcomes":[{"w":70,"text":"The food is warm, the evening is gentle and the whisper from earlier becomes a funny story you retell for years.","tone":"good","effects":[{"t":"needs","delta":{"social":12,"fun":12,"hunger":15,"stress":-8}}]},{"w":30,"text":"{partner} has also made a small plan for the weekend: a day trip, just the two of you. You cannot stop smiling.","tone":"twist","effects":[{"t":"needs","delta":{"social":14,"fun":14,"hunger":12}},{"t":"path","delta":{"luck":1}}]}]},{"id":"sorry","label":"Apologise for doubting them","path":{"family":2,"goodwill":1},"outcomes":[{"w":100,"text":"{partner} laughs and kisses your forehead: \"It is okay. Next time, ask me first.\" You promise.","tone":"good","effects":[{"t":"needs","delta":{"social":10,"stress":-6,"fun":8}}]}]}]$j$::jsonb, 0, 0, 454),
($t$c_car_mechanic$t$, $t$The honest mechanic$t$, $t$Your phone buzzes with a number you saved the other day. "Oga, na the mechanic from Siluko. I dey check on you. How the car dey?" He reminds you about a service due "before the rain starts again".$t$, $t$🔧$t$, $t$The mechanic from Siluko Road$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"service","label":"Book a service","cost":2500,"path":{"hustle":1},"outcomes":[{"w":70,"text":"He does a careful, honest job and shows you every part he changed. You learn a lot.","tone":"good","effects":[{"t":"skill_xp","skill":"mechanic","xp":6},{"t":"needs","delta":{"stress":-3}}]},{"w":30,"text":"During the service he finds a loose part that could have been dangerous. He fixes it for free. Honesty pays.","tone":"twist","effects":[{"t":"skill_xp","skill":"mechanic","xp":6},{"t":"needs","delta":{"stress":-5}},{"t":"path","delta":{"luck":1}}]}]},{"id":"later","label":"Say you will call later","path":{"hustle":-1},"outcomes":[{"w":55,"text":"You forget about it. The warning light reminds you in a worse moment.","tone":"bad","effects":[{"t":"needs","delta":{"stress":5}}]},{"w":45,"text":"You do remember to call next week. No harm done.","tone":"good","effects":[{"t":"needs","delta":{"stress":-1}}]}]}]$j$::jsonb, 0, 0, 455),
($t$c_buka_debt$t$, $t$Mama Osa remembers$t$, $t$You stop at Mama Osa’s buka. She looks at you, then at her notebook, then at you again. "My dear, you owe me ₦2,500. Last time? The wallet?" You had not forgotten. Not completely.$t$, $t$🍛$t$, $t$Mama Osa$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"pay","label":"Pay with an apology","cost":2500,"path":{"goodwill":2,"trouble":-1},"outcomes":[{"w":70,"text":"She nods, rubs her hands and gives you a free portion of pepper soup. \"You are a person with word.\"","tone":"good","effects":[{"t":"needs","delta":{"hunger":12,"social":6}},{"t":"street_cred","delta":1}]},{"w":30,"text":"She tears the page from her notebook, hands you the debt-free page and says she will tell her customers that you are \"someone I trust\".","tone":"twist","effects":[{"t":"needs","delta":{"social":8,"hunger":10}},{"t":"path","delta":{"luck":1}}]}]},{"id":"stall","label":"Say you will pay at the weekend","path":{"goodwill":-1,"trouble":1},"outcomes":[{"w":65,"text":"She looks at you for a long time. \"Weekend,\" she says, writing it down. The warmth in her voice is gone.","tone":"bad","effects":[{"t":"needs","delta":{"stress":5,"social":-4}}]},{"w":35,"text":"She laughs and says, \"Always weekend!\" You laugh too. But you do pay on Saturday.","tone":"funny","effects":[{"t":"needs","delta":{"fun":3}}]}]}]$j$::jsonb, 0, 0, 456),
($t$c_lost_child_aunty$t$, $t$Aunty from the market$t$, $t$You are walking in the market when a woman waves at you with both hands. "My pikin! The one who helped my daughter!" It is the big aunty from Uselu. She hurries over with a bag in her hand and tears in her eyes.$t$, $t$🛍️$t$, $t$The big aunty from Uselu$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"accept","label":"Accept her gift gracefully","path":{"goodwill":1},"outcomes":[{"w":65,"text":"She hands you a bag of fresh vegetables, pepper and a small cash envelope. \"God bless you and your children yet unborn,\" she says.","tone":"good","effects":[{"t":"cash","amount":2500},{"t":"item","id":"tomatoes","qty":2},{"t":"needs","delta":{"social":8}}]},{"w":35,"text":"She introduces you to every trader on the row. For the next month, vendors save you the best produce and greet you by name.","tone":"twist","effects":[{"t":"needs","delta":{"social":12}},{"t":"path","delta":{"luck":1}},{"t":"street_cred","delta":2}]}]},{"id":"refuse","label":"Decline, it was nothing","path":{"goodwill":3,"faith":1},"outcomes":[{"w":55,"text":"She insists, you insist, and you both walk away smiling with something that is not exactly a gift but is worth more.","tone":"good","effects":[{"t":"needs","delta":{"social":8,"stress":-4}}]},{"w":45,"text":"She quietly puts a small gift in your bag when you are not looking. You find it at home and smile for a long time.","tone":"twist","effects":[{"t":"cash","amount":1500},{"t":"needs","delta":{"social":8}},{"t":"path","delta":{"luck":1}}]}]}]$j$::jsonb, 0, 0, 457),
($t$sys_kind_word$t$, $t$A kind word in the street$t$, $t$A neighbour stops you in the street. "I told my sister about what you did for us. She wants to say thank you, but she is shy." Small acts have a way of travelling, and today one has come back to your door.$t$, $t$🌟$t$, $t$A neighbour$t$, $t$system$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"smile","label":"Smile and say it was nothing","effects":[{"t":"needs","delta":{"social":6,"stress":-5}}],"outcome":"You smile, the neighbour smiles, and the whole street seems a little warmer for a while."},{"id":"invite","label":"Invite her to chat","cost":300,"effects":[{"t":"needs","delta":{"social":10,"fun":5}},{"t":"path","delta":{"goodwill":1}}],"outcome":"You share a short chat and a cold drink. A new friend, a good morning."}]$j$::jsonb, 0, 0, 958),
($t$sys_rumour_travels$t$, $t$Word on the street$t$, $t$You overhear two people at the junction talking about "that person from Ugbowo" and, to your surprise, it is you. People always talk. It is what they say that matters.$t$, $t$🗣️$t$, $t$The junction$t$, $t$system$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"listen","label":"Listen quietly","ignore":true,"effects":[{"t":"needs","delta":{"stress":2}}],"outcome":"You hear that you are known, for better or for worse. You file it away and carry on."},{"id":"greet","label":"Greet them warmly","effects":[{"t":"needs","delta":{"social":5}}],"outcome":"They look surprised, then laugh. \"We were saying good things,\" one says. Maybe."}]$j$::jsonb, 0, 0, 959),
($t$sys_quiet_knock$t$, $t$A quiet knock$t$, $t$Someone knocks gently at your door. A child stands there, holding a small paper bag. "My mama said to give you this," she whispers, and runs off before you can ask. Inside is a small thank-you from someone you cannot place.$t$, $t$🚪$t$, $t$Your door$t$, $t$system$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"keep","label":"Enjoy the thoughtful gift","effects":[{"t":"needs","delta":{"hunger":10,"social":6,"stress":-4}}],"outcome":"You open it. It is a small warm snack, and a note that says only \"Thank you\". You eat it slowly, smiling."},{"id":"find","label":"Try to find who sent it","ignore":true,"effects":[{"t":"needs","delta":{"social":5}}],"outcome":"You ask around for an hour. Nobody admits it, but three people smile in a way that tells you the story."}]$j$::jsonb, 0, 0, 960),
($t$path_blessing_gift$t$, $t$A stranger blesses you$t$, $t$A woman you do not know taps your shoulder at the junction. "I do not know your name, but I heard what you did for people around here. God bless you, my child." She presses a little envelope into your palm.$t$, $t$🙏🏽$t$, $t$A stranger$t$, $t$system$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"take","label":"Thank her and accept","effects":[{"t":"cash","amount":2500},{"t":"needs","delta":{"social":6,"stress":-6}}],"outcome":"You open it later and find ₦2,500. You will not forget this day."},{"id":"share","label":"Thank her and share it","effects":[{"t":"cash","amount":1200},{"t":"needs","delta":{"social":10,"stress":-8}},{"t":"path","delta":{"goodwill":1}}],"outcome":"You pass half of it to a hungry boy on the corner. His smile is better than any money."},{"id":"decline","label":"Politely decline","ignore":true,"effects":[{"t":"needs","delta":{"stress":-5,"social":4}}],"outcome":"She laughs, squeezes your hand and says, \"Then keep the blessing.\" Somehow, that is worth more."}]$j$::jsonb, 0, 0, 961),
($t$path_blessing_food$t$, $t$Plate on the house$t$, $t$Mama Eki waves you over at the buka with a wide smile. "Today your plate is on the house. People say good things about you, and I never forget good people." She is already holding a hot plate of rice and stew.$t$, $t$🍛$t$, $t$Mama Eki$t$, $t$system$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"eat","label":"Eat it gratefully","effects":[{"t":"needs","delta":{"hunger":28,"social":5,"stress":-5}},{"t":"item","id":"jollof_pack","qty":1}],"outcome":"The rice is hot and the stew is perfect. For ten minutes, the day seems made of food and kindness."},{"id":"pay","label":"Insist on paying something","cost":500,"effects":[{"t":"needs","delta":{"hunger":30,"social":8}},{"t":"path","delta":{"goodwill":1}}],"outcome":"She waves your coins away but accepts them in the end, and gives you extra meat."}]$j$::jsonb, 0, 0, 962),
($t$path_blessing_ride$t$, $t$A ride that is already paid$t$, $t$A keke driver pulls up beside you. "Oga, you no dey remember me, but you help my brother last month. Enter, today na free." He says it with the determination of a man who has already decided.$t$, $t$🛺$t$, $t$Keke driver$t$, $t$system$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"ride","label":"Take the free ride","effects":[{"t":"needs","delta":{"social":6,"stress":-6,"fun":4}},{"t":"cash","amount":1000}],"outcome":"You ride in comfort, listen to his music and arrive early. He refuses payment with a smile."},{"id":"walk","label":"Say thanks, but walk","ignore":true,"effects":[{"t":"item","id":"bottled_water","qty":1},{"t":"needs","delta":{"social":3}}],"outcome":"He insists on at least giving you a bottle of water. You accept that."}]$j$::jsonb, 0, 0, 963),
($t$path_police_chat$t$, $t$Officers want a word$t$, $t$Two officers approach you near Ring Road. "Good afternoon. We are following up on a few complaints in this area, and your name came up. Please answer a few questions." In this fictional scene, your reputation has travelled further than you wished.$t$, $t$🚓$t$, $t$Two officers$t$, $t$system$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"coop","label":"Cooperate fully","effects":[{"t":"needs","delta":{"stress":6}},{"t":"path","delta":{"trouble":-2}},{"t":"street_cred","delta":1}],"outcome":"You answer calmly. After half an hour they thank you and let you go. Your stress drops, and so does your reputation for cutting corners."},{"id":"lawyer","label":"Call a lawyer friend","cost":2000,"effects":[{"t":"needs","delta":{"stress":-2}},{"t":"path","delta":{"trouble":-1}}],"outcome":"Your friend arrives and everything is settled with a short, formal statement."},{"id":"dodge","label":"Dodge the questions","ignore":true,"effects":[{"t":"needs","delta":{"stress":12}},{"t":"street_cred","delta":-2},{"t":"path","delta":{"trouble":1}}],"outcome":"The officers do not look happy. They let you go, with a warning and a note beside your name."}]$j$::jsonb, 0, 0, 964),
($t$path_efcc_notice$t$, $t$A letter from EFCC$t$, $t$A formal letter arrives, asking you to "come in for a short interview" about quick-money accounts in your area. In this fictional scene, you are not accused of anything, but the tone is cold and your hands are not steady.$t$, $t$📬$t$, $t$EFCC office$t$, $t$system$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"go","label":"Go in and answer honestly","effects":[{"t":"needs","delta":{"stress":8}},{"t":"path","delta":{"trouble":-3}},{"t":"street_cred","delta":1}],"outcome":"You answer every question calmly. They thank you for your time and ask you to stay reachable. You walk out lighter than you walked in."},{"id":"lawyer","label":"Go in with a lawyer","cost":3000,"effects":[{"t":"needs","delta":{"stress":-3}},{"t":"path","delta":{"trouble":-2}}],"outcome":"Your lawyer does the talking. You leave with a clean note and a lighter heart."},{"id":"ignore","label":"Ignore the letter","ignore":true,"effects":[{"t":"needs","delta":{"stress":15}},{"t":"street_cred","delta":-3},{"t":"path","delta":{"trouble":1}}],"outcome":"The letter does not go away. Neither does the worry. Next week a second, shorter note arrives."}]$j$::jsonb, 0, 0, 965),
($t$a1_1$t$, $t$The caster who needs a hand$t$, $t$On Igun Street the old caster Mr. Iyamu is trying to lift a heavy clay mould by himself. His apprentice has gone to a naming ceremony. "My friend," he says, breathless, "I will not ask for much. Help me today and I will show you something of this work."$t$, $t$⚒️$t$, $t$Mr. Iyamu, bronze caster$t$, $t$daily$t$, $j${}$j$::jsonb, $j${"goodwill":0.5}$j$::jsonb, $j$[{"id":"help","label":"Help him for the day","path":{"goodwill":3,"hustle":1},"outcomes":[{"w":60,"text":"You carry, sweep and fetch water until your arms ache. At dusk he nods: \"You have good hands. Come back in two days.\"","tone":"good","effects":[{"t":"needs","delta":{"energy":-12,"hygiene":-10,"social":5}},{"t":"skill_xp","skill":"business","xp":3},{"t":"follow_up","moment":"a1_2_help","delay_hours":48,"chance":100}]},{"w":40,"text":"A foreign visitor stops by and buys a small plaque while you hold the stall. Mr. Iyamu is delighted and promises you a share of the next sale.","tone":"twist","effects":[{"t":"needs","delta":{"energy":-10,"hygiene":-8,"social":6}},{"t":"cash","amount":1500},{"t":"follow_up","moment":"a1_2_help","delay_hours":48,"chance":100}]}]},{"id":"buy","label":"Buy a small piece and chat","cost":1500,"path":{"family":1,"goodwill":1},"outcomes":[{"w":100,"text":"He tells you how a plaque is made, from wax to fire. You leave with a small piece and a head full of stories. \"Come back when you want to learn more,\" he says.","tone":"good","effects":[{"t":"needs","delta":{"social":6,"fun":6}},{"t":"follow_up","moment":"a1_2_buy","delay_hours":48,"chance":100}]}]},{"id":"pass","label":"Pass politely, you are busy","path":{"hustle":-1},"outcomes":[{"w":100,"text":"He smiles, says \"Another day\", and manages the mould himself with a grunt and a laugh. You walk on with a small wave.","tone":"good","effects":[{"t":"needs","delta":{"stress":1}},{"t":"follow_up","moment":"a1_2_pass","delay_hours":72,"chance":100}]}]}]$j$::jsonb, 90, 0.6, 466),
($t$a1_2_help$t$, $t$Hands in the clay$t$, $t$Back on Igun Street the workshop is hot. Mr. Iyamu hands you a wax model to finish. "Take your time," he says. "Rushing ruins the work." On the bench: a smooth wax plaque, a small tool and a lot of patience.$t$, $t$🔥$t$, $t$Mr. Iyamu, bronze caster$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"careful","label":"Follow his instructions carefully","path":{"hustle":-2,"goodwill":1},"outcomes":[{"w":70,"text":"Your lines are slow and clean. Mr. Iyamu nods, and in his silence you read approval.","tone":"good","effects":[{"t":"needs","delta":{"energy":-6,"stress":-4}},{"t":"skill_xp","skill":"business","xp":4},{"t":"follow_up","moment":"a1_3_proud","delay_hours":48,"chance":100}]},{"w":30,"text":"Your hand is too careful and the lines are stiff. Mr. Iyamu pats your shoulder: \"It is a start.\" The mould is fine, but not perfect.","tone":"bad","effects":[{"t":"needs","delta":{"energy":-6,"stress":3}},{"t":"follow_up","moment":"a1_3_mend","delay_hours":48,"chance":100}]}]},{"id":"own","label":"Try your own design idea","path":{"hustle":3,"trouble":1},"outcomes":[{"w":35,"text":"Your idea is bold and strange. Mr. Iyamu is silent for a long time, then smiles: \"Eh. That one is different. Let us cast it.\"","tone":"twist","effects":[{"t":"needs","delta":{"energy":-6,"fun":6}},{"t":"path","delta":{"luck":1}},{"t":"skill_xp","skill":"business","xp":5},{"t":"follow_up","moment":"a1_3_proud","delay_hours":48,"chance":100}],"path_w":{"luck":1}},{"w":65,"text":"The wax slips and the model cracks. Mr. Iyamu sighs. \"Experiments are good, but first learn the basics.\" You stare at the crack.","tone":"bad","effects":[{"t":"needs","delta":{"stress":6,"energy":-6}},{"t":"follow_up","moment":"a1_3_mend","delay_hours":48,"chance":100}]}]},{"id":"ask","label":"Ask him to show you again","path":{"goodwill":1,"faith":1},"outcomes":[{"w":100,"text":"He shows you again, then again. Teaching is part of the craft too. By evening your piece looks like something a person could be proud of.","tone":"good","effects":[{"t":"needs","delta":{"energy":-5,"social":5}},{"t":"skill_xp","skill":"business","xp":3},{"t":"follow_up","moment":"a1_3_proud","delay_hours":48,"chance":100}]}]}]$j$::jsonb, 0, 0, 467),
($t$a1_2_buy$t$, $t$A lesson, for a fee$t$, $t$Mr. Iyamu remembers you. "My friend! The one who listens." He offers a short lesson: a morning at the bench, to make a very small piece, for ₦2,000 that "pays for the wax and the fire".$t$, $t$🪙$t$, $t$Mr. Iyamu, bronze caster$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"pay","label":"Pay and learn","cost":2000,"path":{"hustle":1,"family":1},"outcomes":[{"w":75,"text":"By lunchtime you have a small bronze keyring in your palm that you made yourself. It is not perfect. It is yours.","tone":"good","effects":[{"t":"needs","delta":{"fun":10,"energy":-6}},{"t":"skill_xp","skill":"business","xp":4},{"t":"follow_up","moment":"a1_3_proud","delay_hours":48,"chance":100}]},{"w":25,"text":"You make a keyring that looks like a small potato. Mr. Iyamu laughs for a long time. \"A very good potato,\" he says.","tone":"funny","effects":[{"t":"needs","delta":{"fun":12,"energy":-6}},{"t":"follow_up","moment":"a1_3_proud","delay_hours":48,"chance":100}]}]},{"id":"haggle","label":"Try to haggle the price","path":{"hustle":2},"outcomes":[{"w":40,"text":"He laughs and brings the price down to ₦1,200. \"You have a market tongue,\" he says.","tone":"good","effects":[{"t":"needs","delta":{"fun":5}},{"t":"cash","amount":-1200,"up_to":true},{"t":"skill_xp","skill":"business","xp":4},{"t":"follow_up","moment":"a1_3_proud","delay_hours":48,"chance":100}]},{"w":60,"text":"He raises an eyebrow. \"This craft is not for haggling,\" he says, gently but firmly. You pay the full price and feel small.","tone":"bad","effects":[{"t":"cash","amount":-2000,"up_to":true},{"t":"needs","delta":{"stress":3}},{"t":"follow_up","moment":"a1_3_mend","delay_hours":48,"chance":100}]}]},{"id":"no","label":"Say you cannot afford it today","path":{"hustle":-1},"outcomes":[{"w":100,"text":"He nods without judgment. \"Another time. The fire will still be here.\" You leave with respect and a little regret.","tone":"good","effects":[{"t":"needs","delta":{"stress":1}},{"t":"follow_up","moment":"a1_end_quiet","delay_hours":72,"chance":100}]}]}]$j$::jsonb, 0, 0, 468),
($t$a1_2_pass$t$, $t$The caster remembers$t$, $t$Passing Igun Street again you hear your name. Mr. Iyamu is waving a small hammer in the air. "My friend! The busy one! The mould was heavy, but I managed. Come, sit. I want to tell you something about patience."$t$, $t$🔔$t$, $t$Mr. Iyamu, bronze caster$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"sit","label":"Sit down and listen","path":{"goodwill":2,"faith":1},"outcomes":[{"w":100,"text":"He talks about the first plaque he ever made and the mistakes he kept. By the end you feel the weight of his years in a good way.","tone":"good","effects":[{"t":"needs","delta":{"stress":-8,"social":6}},{"t":"follow_up","moment":"a1_end_quiet","delay_hours":72,"chance":100}]}]},{"id":"wave","label":"Wave and hurry on","path":{"goodwill":-1},"outcomes":[{"w":100,"text":"He lowers his hand slowly and goes back to work. Something quiet closes between you.","tone":"bad","effects":[{"t":"needs","delta":{"stress":3,"social":-2}},{"t":"follow_up","moment":"a1_end_quiet","delay_hours":96,"chance":100}]}]}]$j$::jsonb, 0, 0, 469),
($t$a1_3_proud$t$, $t$A customer for the plaque$t$, $t$A customer arrives, a man in a clean white shirt, asking for a custom plaque for his family house. Mr. Iyamu glances at you. "This one can be yours. I will guide you." The price is yours to set.$t$, $t$🏺$t$, $t$Mr. Iyamu, bronze caster$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"fair","label":"Set a fair price","path":{"goodwill":2,"hustle":1},"outcomes":[{"w":75,"text":"The customer nods, pays ₦4,000, and tells three friends. Mr. Iyamu puts a hand on your shoulder.","tone":"good","effects":[{"t":"cash","amount":4000},{"t":"needs","delta":{"social":6}},{"t":"skill_xp","skill":"business","xp":5},{"t":"follow_up","moment":"a1_4_stall","delay_hours":72,"chance":100}]},{"w":25,"text":"The customer says it is too little, and adds ₦1,500 for the care you put in. A very rare thing.","tone":"twist","effects":[{"t":"cash","amount":5500},{"t":"needs","delta":{"social":8}},{"t":"path","delta":{"luck":1}},{"t":"follow_up","moment":"a1_4_stall","delay_hours":72,"chance":100}]}]},{"id":"high","label":"Name a high price","path":{"hustle":3,"goodwill":-1},"outcomes":[{"w":40,"text":"The customer pays ₦6,000 without a word. Mr. Iyamu looks at you with a mixture of pride and concern.","tone":"good","effects":[{"t":"cash","amount":6000},{"t":"skill_xp","skill":"business","xp":4},{"t":"follow_up","moment":"a1_4_stall","delay_hours":72,"chance":100}]},{"w":60,"text":"The customer shakes his head and walks away. Mr. Iyamu says, \"A price is a conversation, not a wall.\"","tone":"bad","effects":[{"t":"needs","delta":{"stress":5}},{"t":"follow_up","moment":"a1_4_stall","delay_hours":72,"chance":100}]}]},{"id":"gift","label":"Offer a discount for a good cause","path":{"goodwill":3,"family":1},"outcomes":[{"w":100,"text":"The customer is touched and brings his whole family to see the finished piece. You earn ₦2,500 and a whole new set of friends.","tone":"good","effects":[{"t":"cash","amount":2500},{"t":"needs","delta":{"social":10}},{"t":"path","delta":{"luck":1}},{"t":"follow_up","moment":"a1_4_stall","delay_hours":72,"chance":100}]}]}]$j$::jsonb, 0, 0, 470),
($t$a1_3_mend$t$, $t$Mending the mistake$t$, $t$The cracked piece sits on the bench like a small accusation. Mr. Iyamu says nothing. He is waiting to see what you will do. The wax could be reused, but the work, and the time, are lost.$t$, $t$🩹$t$, $t$Mr. Iyamu, bronze caster$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"own","label":"Own up and offer to pay for the wax","cost":800,"path":{"goodwill":2,"trouble":-1},"outcomes":[{"w":80,"text":"He nods slowly. \"A person who mends his mistakes will make good bronze,\" he says. He hands you a fresh piece of wax.","tone":"good","effects":[{"t":"needs","delta":{"stress":-4,"social":4}},{"t":"skill_xp","skill":"business","xp":4},{"t":"follow_up","moment":"a1_4_stall","delay_hours":72,"chance":100}]},{"w":20,"text":"He refuses the money and says, \"Your honesty is worth more than wax.\" Then he gives you a lecture, a hug and a cup of tea.","tone":"twist","effects":[{"t":"needs","delta":{"social":8,"stress":-6}},{"t":"path","delta":{"luck":1}},{"t":"follow_up","moment":"a1_4_stall","delay_hours":72,"chance":100}]}]},{"id":"hide","label":"Quietly hide the crack","path":{"trouble":3,"goodwill":-2},"outcomes":[{"w":70,"text":"He finds it in minutes. He looks at you, sighs and says, \"Lies leave a worse crack than clay.\" The air between you cools.","tone":"bad","effects":[{"t":"needs","delta":{"stress":8,"social":-4}},{"t":"street_cred","delta":-1},{"t":"follow_up","moment":"a1_4_stall","delay_hours":96,"chance":60}]},{"w":30,"text":"He does not notice, but you do. All evening, it sits in your stomach.","tone":"good","effects":[{"t":"needs","delta":{"stress":8}},{"t":"follow_up","moment":"a1_4_stall","delay_hours":96,"chance":40}]}]},{"id":"again","label":"Ask for another try, right now","path":{"hustle":2},"outcomes":[{"w":60,"text":"He gives you a second chance and you pour yourself into it. The result is better than the first, and both of you can tell.","tone":"good","effects":[{"t":"needs","delta":{"energy":-8,"stress":-2}},{"t":"skill_xp","skill":"business","xp":5},{"t":"follow_up","moment":"a1_4_stall","delay_hours":72,"chance":100}]},{"w":40,"text":"The second attempt is no better. He pats your back anyway: \"Tomorrow, we begin again.\"","tone":"bad","effects":[{"t":"needs","delta":{"energy":-8,"stress":4}},{"t":"follow_up","moment":"a1_4_stall","delay_hours":72,"chance":100}]}]}]$j$::jsonb, 0, 0, 471),
($t$a1_4_stall$t$, $t$A place at the bench$t$, $t$Mr. Iyamu cleans his hands slowly and clears his throat. "My friend, I am not as young as I was. My apprentice will not be here every day. I can offer you a small corner of this bench, and a small share of what you sell, if you will keep working with me."$t$, $t$🏅$t$, $t$Mr. Iyamu, bronze caster$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"yes","label":"Accept the small corner and the share","path":{"hustle":2,"goodwill":1,"faith":1},"outcomes":[{"w":65,"text":"You shake hands. He puts a small, warm piece of bronze in your hand and says, \"A beginning.\" You leave a part of yourself on that bench.","tone":"good","effects":[{"t":"cash","amount":3000},{"t":"needs","delta":{"social":10,"fun":8}},{"t":"skill_xp","skill":"business","xp":8},{"t":"street_cred","delta":2}]},{"w":35,"text":"On your first day at the bench a tour group arrives and buys everything you have made. Mr. Iyamu laughs: \"I told you these hands were good.\"","tone":"twist","effects":[{"t":"cash","amount":5500},{"t":"needs","delta":{"social":12,"fun":10}},{"t":"skill_xp","skill":"business","xp":8},{"t":"path","delta":{"luck":1}},{"t":"street_cred","delta":2}]}]},{"id":"visit","label":"Thank him, but only visit sometimes","path":{"family":1},"outcomes":[{"w":100,"text":"He smiles, a little wistful. \"The door is always open,\" he says. You visit from time to time, and every visit ends with a story.","tone":"good","effects":[{"t":"cash","amount":1500},{"t":"needs","delta":{"social":8,"stress":-5}}]}]},{"id":"no","label":"Say your path is somewhere else","path":{"hustle":1,"goodwill":1},"outcomes":[{"w":100,"text":"He nods, with respect. \"Then walk it well,\" he says. You take a small piece of bronze he gives you and carry it like a promise.","tone":"good","effects":[{"t":"needs","delta":{"social":6,"stress":-3}},{"t":"path","delta":{"faith":1}}]}]}]$j$::jsonb, 0, 0, 472),
($t$a1_end_quiet$t$, $t$The sound of hammers$t$, $t$You walk down Igun Street again. The hammers ring, as they have rung for generations. Mr. Iyamu is bent over his work, humming. He looks up, nods once, and goes back to the bronze. You carry that quiet nod with you.$t$, $t$🔔$t$, $t$Igun Street$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"stop","label":"Stop and say a proper hello","path":{"goodwill":1,"faith":1},"outcomes":[{"w":100,"text":"He lays down his hammer and shakes your hand. \"Some doors open slowly,\" he says. You buy a small bronze keyring for ₦800.","tone":"good","effects":[{"t":"cash","amount":-800,"up_to":true},{"t":"needs","delta":{"social":6,"stress":-5}},{"t":"skill_xp","skill":"business","xp":2}]}]},{"id":"walk","label":"Nod and keep walking","path":{"hustle":1},"outcomes":[{"w":100,"text":"A nod is a whole conversation in Benin. You walk on, a little lighter than before.","tone":"good","effects":[{"t":"needs","delta":{"stress":-2}}]}]}]$j$::jsonb, 0, 0, 473),
($t$a2_1$t$, $t$A car too cheap to be true$t$, $t$At the Sapele Road tokunbo lot, a dealer named Tunde waves you over to a clean sedan. "Just cleared from the port, my brother. ₦100,000 less than the others. I have a man ready to pay more, but I like your face."$t$, $t$🚙$t$, $t$Tunde, car dealer$t$, $t$daily$t$, $j${"min_days":2}$j$::jsonb, $j${"hustle":0.4}$j$::jsonb, $j$[{"id":"papers","label":"Ask to see the papers first","path":{"hustle":1,"trouble":-1},"outcomes":[{"w":100,"text":"Tunde’s smile stays, but it is a little thinner. \"Come back tomorrow. The papers are with my oga.\" You smell a story.","tone":"good","effects":[{"t":"needs","delta":{"stress":2}},{"t":"follow_up","moment":"a2_2_papers","delay_hours":24,"chance":100}]}]},{"id":"mech","label":"Bring a mechanic friend to check it","cost":1000,"path":{"hustle":1,"goodwill":1},"outcomes":[{"w":100,"text":"Your friend knocks, listens and frowns. \"Come back tomorrow,\" Tunde says quickly. \"We can talk after proper checking.\"","tone":"good","effects":[{"t":"needs","delta":{"stress":2}},{"t":"skill_xp","skill":"mechanic","xp":3},{"t":"follow_up","moment":"a2_2_mech","delay_hours":24,"chance":100}]}]},{"id":"deposit","label":"Pay a quick deposit to hold it","cost":5000,"path":{"hustle":3,"trouble":2},"outcomes":[{"w":100,"text":"Tunde writes a receipt on a torn paper and shakes your hand with both of his. \"God will bless this deal,\" he says. His phone rings immediately.","tone":"good","effects":[{"t":"needs","delta":{"stress":6}},{"t":"follow_up","moment":"a2_2_rush","delay_hours":24,"chance":100}]}]}]$j$::jsonb, 90, 0.6, 474),
($t$a2_2_papers$t$, $t$The papers$t$, $t$Tunde returns with a bundle of papers in a nylon bag. The stamps look right, but the ink is strangely fresh. "Everything is complete," he says. "Even customs." You hold the pages up to the light.$t$, $t$📑$t$, $t$Tunde, car dealer$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"verify","label":"Insist on verifying them first","path":{"trouble":-2,"hustle":1},"outcomes":[{"w":55,"text":"The verification takes a day, but the papers are real. Tunde laughs, relieved. \"You are careful, my brother. I like careful people.\"","tone":"good","effects":[{"t":"needs","delta":{"stress":-2}},{"t":"follow_up","moment":"a2_3_deal","delay_hours":24,"chance":100}]},{"w":45,"text":"The papers are not real. Tunde disappears into the back of the lot, and you walk away with a lesson and a story.","tone":"bad","effects":[{"t":"needs","delta":{"stress":4}},{"t":"street_cred","delta":1},{"t":"follow_up","moment":"a2_3_walk","delay_hours":24,"chance":100}]}]},{"id":"trust","label":"Accept the papers, they look fine","path":{"trouble":2,"hustle":2},"outcomes":[{"w":70,"text":"Later you learn they were forged. You lose time and some of your confidence. Luckily, you had not paid yet.","tone":"bad","effects":[{"t":"needs","delta":{"stress":8}},{"t":"follow_up","moment":"a2_3_walk","delay_hours":24,"chance":100}],"path_w":{"trouble":1}},{"w":30,"text":"The papers are genuine, by pure luck. You have a car deal and a very fast heartbeat.","tone":"good","effects":[{"t":"needs","delta":{"stress":4}},{"t":"follow_up","moment":"a2_3_deal","delay_hours":24,"chance":100}],"path_w":{"luck":1.5}}]},{"id":"walk","label":"Say thanks, and walk away","path":{"trouble":-1},"outcomes":[{"w":100,"text":"Tunde watches you leave, and you feel a small wave of relief. Not every deal is meant to be.","tone":"good","effects":[{"t":"needs","delta":{"stress":-3}},{"t":"follow_up","moment":"a2_3_walk","delay_hours":24,"chance":100}]}]}]$j$::jsonb, 0, 0, 475),
($t$a2_2_mech$t$, $t$The mechanic’s verdict$t$, $t$Your mechanic friend wipes his hands on a rag and delivers the verdict: "The engine is okay, but the gearbox has had a hard life. The car is not a lie, but it is not the bargain Tunde says." Tunde leans against a pole and pretends not to listen.$t$, $t$🧰$t$, $t$Your mechanic friend$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"negotiate","label":"Negotiate the price down","path":{"hustle":2},"outcomes":[{"w":55,"text":"With the mechanic’s notes in hand, you push the price down. Tunde sighs, calls someone, and agrees.","tone":"good","effects":[{"t":"needs","delta":{"stress":-2}},{"t":"skill_xp","skill":"mechanic","xp":4},{"t":"follow_up","moment":"a2_3_deal","delay_hours":24,"chance":100}],"path_w":{"luck":1}},{"w":45,"text":"Tunde refuses to move an inch. \"Take it or leave it,\" he says. You leave it.","tone":"bad","effects":[{"t":"needs","delta":{"stress":3}},{"t":"skill_xp","skill":"mechanic","xp":4},{"t":"follow_up","moment":"a2_3_walk","delay_hours":24,"chance":100}]}]},{"id":"leave","label":"Thank Tunde and leave","path":{"hustle":-1,"trouble":-1},"outcomes":[{"w":100,"text":"You walk away with your money, your mechanic friend and a sense that you made a sensible choice.","tone":"good","effects":[{"t":"needs","delta":{"stress":-4}},{"t":"skill_xp","skill":"mechanic","xp":3},{"t":"follow_up","moment":"a2_3_walk","delay_hours":24,"chance":100}]}]},{"id":"buy","label":"Buy it anyway, you like it","path":{"hustle":2},"outcomes":[{"w":50,"text":"The gearbox holds. For a while. You are happy, and your mechanic friend is a bit grim.","tone":"good","effects":[{"t":"needs","delta":{"fun":6}},{"t":"follow_up","moment":"a2_3_deal","delay_hours":24,"chance":100}]},{"w":50,"text":"The gearbox starts talking to you three days later. You learn more about gearboxes than you ever wanted.","tone":"bad","effects":[{"t":"cash","amount":-2000,"up_to":true},{"t":"needs","delta":{"stress":8}},{"t":"follow_up","moment":"a2_3_walk","delay_hours":24,"chance":100}]}]}]$j$::jsonb, 0, 0, 476),
($t$a2_2_rush$t$, $t$Tunde stops answering$t$, $t$The day after you paid the deposit Tunde’s phone starts ringing out. At the lot, his friend shrugs: "He went to Warri to see the papers." Your ₦5,000 deposit and the torn receipt suddenly feel very light.$t$, $t$📵$t$, $t$Tunde, car dealer$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"wait","label":"Wait at the lot until he returns","path":{"hustle":1},"outcomes":[{"w":40,"text":"Tunde turns up at dusk, apologises, and finally shows the papers. They look fine. \"Delays are normal,\" he says.","tone":"good","effects":[{"t":"needs","delta":{"stress":-2}},{"t":"follow_up","moment":"a2_3_deal","delay_hours":24,"chance":100}],"path_w":{"luck":1.3}},{"w":60,"text":"Tunde does not come back. Two days of waiting end with a very quiet drive home.","tone":"bad","effects":[{"t":"needs","delta":{"stress":10,"energy":-6}},{"t":"follow_up","moment":"a2_3_walk","delay_hours":24,"chance":100}]}]},{"id":"report","label":"Report it to the police","path":{"trouble":-2,"goodwill":1},"outcomes":[{"w":50,"text":"The officers take your statement. A week later you learn Tunde has been dodging other people too. You get half your deposit back.","tone":"twist","effects":[{"t":"cash","amount":2500},{"t":"needs","delta":{"stress":4}},{"t":"street_cred","delta":2},{"t":"follow_up","moment":"a2_3_walk","delay_hours":24,"chance":100}]},{"w":50,"text":"The police note it, and say they will \"look into it\". You file the receipt in your memory under \"lessons\".","tone":"bad","effects":[{"t":"needs","delta":{"stress":6}},{"t":"follow_up","moment":"a2_3_walk","delay_hours":24,"chance":100}]}]},{"id":"chase","label":"Go looking for him yourself","path":{"trouble":2,"hustle":2},"outcomes":[{"w":70,"text":"You spend a whole afternoon visiting other lots, asking questions and being told lies. You learn who Tunde is. You do not find him.","tone":"bad","effects":[{"t":"needs","delta":{"stress":10,"energy":-10}},{"t":"follow_up","moment":"a2_3_walk","delay_hours":24,"chance":100}]},{"w":30,"text":"You find him at a roadside buka, eating rice. He is so surprised that he returns your deposit on the spot.","tone":"twist","effects":[{"t":"cash","amount":5000},{"t":"needs","delta":{"stress":-4}},{"t":"path","delta":{"luck":1}},{"t":"follow_up","moment":"a2_3_walk","delay_hours":24,"chance":100}]}]}]$j$::jsonb, 0, 0, 477),
($t$a2_3_deal$t$, $t$The keys$t$, $t$Tunde hands you a ring of keys with the pride of a man who has just proved something. The sedan shines under the lot’s single bulb. "Congratulations, my brother." The deal is done, or almost done.$t$, $t$🔑$t$, $t$Tunde, car dealer$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"sell","label":"Pass the deal to a friend for a fee","path":{"hustle":2,"goodwill":1},"outcomes":[{"w":60,"text":"Your friend buys the car happily. Tunde pays you ₦4,000 for bringing the customer. You walk away with a skill and a new reputation.","tone":"good","effects":[{"t":"cash","amount":4000},{"t":"needs","delta":{"social":6}},{"t":"skill_xp","skill":"business","xp":6},{"t":"follow_up","moment":"a2_4_news","delay_hours":72,"chance":100}]},{"w":40,"text":"Your friend buys the car, and Tunde, impressed, gives you ₦4,000 and a standing offer to bring any customer.","tone":"twist","effects":[{"t":"cash","amount":4000},{"t":"needs","delta":{"social":8}},{"t":"path","delta":{"luck":1}},{"t":"skill_xp","skill":"business","xp":6},{"t":"follow_up","moment":"a2_4_news","delay_hours":72,"chance":100}]}]},{"id":"drive","label":"Keep the dream alive, test drive it","path":{"hustle":1},"outcomes":[{"w":60,"text":"You drive around the lot twice, sing along with the radio and feel like a person with a future. The car is not yours, but the afternoon is.","tone":"funny","effects":[{"t":"needs","delta":{"fun":14,"stress":-6}},{"t":"skill_xp","skill":"driving","xp":5},{"t":"follow_up","moment":"a2_4_news","delay_hours":72,"chance":100}]},{"w":40,"text":"The car stalls on the way out of the lot. Tunde says \"It is the heat.\" You are not so sure.","tone":"bad","effects":[{"t":"needs","delta":{"stress":4,"fun":4}},{"t":"follow_up","moment":"a2_4_news","delay_hours":72,"chance":100}]}]},{"id":"thanks","label":"Thank him and say you will think","path":{"hustle":-1},"outcomes":[{"w":100,"text":"Tunde is disappointed but polite. You walk away with your money and a better sense of the road.","tone":"good","effects":[{"t":"needs","delta":{"stress":-3}},{"t":"follow_up","moment":"a2_4_news","delay_hours":96,"chance":100}]}]}]$j$::jsonb, 0, 0, 478),
($t$a2_3_walk$t$, $t$What the lot says$t$, $t$The lot is buzzing the next day. A group of dealers argue loudly about a "bad deal" and an unlucky buyer. Someone sees you and says, "Eh! You were the one who nearly bought from Tunde!" Everyone turns.$t$, $t$🗣️$t$, $t$Sapele Road tokunbo lot$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"laugh","label":"Laugh and tell the story","path":{"goodwill":1,"hustle":1},"outcomes":[{"w":70,"text":"You tell the story with gestures. The lot roars with laughter, and a stranger buys you a cold drink for being a good sport.","tone":"funny","effects":[{"t":"needs","delta":{"fun":10,"social":8}},{"t":"skill_xp","skill":"charisma","xp":4},{"t":"follow_up","moment":"a2_4_news","delay_hours":72,"chance":100}]},{"w":30,"text":"A seasoned dealer pulls you aside and gives you real tips about papers and gearboxes. A real gift.","tone":"good","effects":[{"t":"needs","delta":{"social":5}},{"t":"skill_xp","skill":"mechanic","xp":5},{"t":"follow_up","moment":"a2_4_news","delay_hours":72,"chance":100}]}]},{"id":"quiet","label":"Keep quiet and move on","path":{"hustle":-1},"outcomes":[{"w":100,"text":"You say nothing. A dealer nods in respect. You leave with your head high and your wallet intact.","tone":"good","effects":[{"t":"needs","delta":{"stress":-3}},{"t":"follow_up","moment":"a2_4_news","delay_hours":96,"chance":100}]}]}]$j$::jsonb, 0, 0, 479),
($t$a2_4_news$t$, $t$News from Sapele Road$t$, $t$A friend from the lot calls with news. "You remember Tunde? The police picked him up for fake papers. Many people lost money. You were wise." Or maybe: "Tunde has opened a bigger lot, with a signboard and everything." You are not sure which version is true.$t$, $t$📰$t$, $t$A friend at the lot$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"glad","label":"Feel relieved and thank your stars","path":{"faith":1,"trouble":-1},"outcomes":[{"w":55,"text":"You say a small prayer for those who lost money. You are more careful with deals from that day on.","tone":"good","effects":[{"t":"needs","delta":{"stress":-5}},{"t":"path","delta":{"faith":1}},{"t":"street_cred","delta":1}],"path_w":{"trouble":-1}},{"w":45,"text":"It turns out Tunde repaid a few of his victims. Life is stranger than any dealer’s story.","tone":"twist","effects":[{"t":"needs","delta":{"social":3}},{"t":"path","delta":{"luck":1}}]}]},{"id":"visit","label":"Go and see the new lot out of curiosity","path":{"hustle":1},"outcomes":[{"w":60,"text":"The signboard says \"Honest Tunde Motors\". You laugh until you hiccup. Tunde waves at you from a distance, a little sheepish.","tone":"funny","effects":[{"t":"needs","delta":{"fun":10}}]},{"w":40,"text":"A few good cars, a good price and a better story. You buy nothing but take his card, just in case.","tone":"good","effects":[{"t":"needs","delta":{"social":4}},{"t":"skill_xp","skill":"business","xp":3}]}]}]$j$::jsonb, 0, 0, 480),
($t$a3_1$t$, $t$Mama Blessing’s new buka$t$, $t$A new buka has opened near Ekenwan. Mama Blessing, a widow with two children, sells rice and stew from a small wooden shed. The food is good, but the street is quiet. A bigger buka up the road has loud music and a big signboard. She looks tired.$t$, $t$🍛$t$, $t$Mama Blessing$t$, $t$daily$t$, $j${}$j$::jsonb, $j${"goodwill":0.6}$j$::jsonb, $j$[{"id":"sign","label":"Suggest a clear signboard and a menu","path":{"goodwill":2,"hustle":2},"outcomes":[{"w":100,"text":"You help her paint a bright signboard and write a short menu in chalk. She cries a little. \"God sent you,\" she says. Tomorrow will tell.","tone":"good","effects":[{"t":"needs","delta":{"social":6,"energy":-5}},{"t":"skill_xp","skill":"business","xp":3},{"t":"follow_up","moment":"a3_2_sign","delay_hours":36,"chance":100}]}]},{"id":"friends","label":"Bring your friends to eat","cost":1500,"path":{"goodwill":3,"family":1},"outcomes":[{"w":100,"text":"Six friends, six plates and a lot of laughing. Mama Blessing stops counting orders and just smiles. People walking past slow down to look.","tone":"good","effects":[{"t":"needs","delta":{"social":10,"hunger":18,"fun":8}},{"t":"follow_up","moment":"a3_2_friends","delay_hours":36,"chance":100}]}]},{"id":"loan","label":"Lend her ₦3,000 for fresh stock","cost":3000,"path":{"goodwill":3,"hustle":1},"outcomes":[{"w":100,"text":"She holds the money like it might fly away. \"I will pay you back with interest,\" she says. You laugh and say there is no interest in friendship.","tone":"good","effects":[{"t":"needs","delta":{"social":8}},{"t":"follow_up","moment":"a3_2_loan","delay_hours":36,"chance":100}]}]}]$j$::jsonb, 90, 0.6, 481),
($t$a3_2_sign$t$, $t$The signboard works$t$, $t$Two days later, Mama Blessing’s shed has a small queue. People point at the signboard, read the menu aloud and order. But the owner of the bigger buka walks past slowly, looking at the queue, and then at you.$t$, $t$🪧$t$, $t$Mama Blessing$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"smile","label":"Smile and keep helping Mama Blessing","path":{"goodwill":1,"hustle":1},"outcomes":[{"w":60,"text":"The rival frowns, then walks away. The queue grows. Mama Blessing’s eyes shine.","tone":"good","effects":[{"t":"needs","delta":{"social":6,"energy":-4}},{"t":"follow_up","moment":"a3_3_rush","delay_hours":36,"chance":100}]},{"w":40,"text":"The rival whispers something in Mama Blessing’s ear. Her smile falters. She tells you about it later.","tone":"bad","effects":[{"t":"needs","delta":{"stress":4}},{"t":"follow_up","moment":"a3_3_rival","delay_hours":36,"chance":100}]}]},{"id":"talk","label":"Greet the rival politely","path":{"goodwill":2},"outcomes":[{"w":50,"text":"He is surprised by your manners. He mutters something about \"competition being healthy\" and leaves.","tone":"twist","effects":[{"t":"needs","delta":{"social":5}},{"t":"path","delta":{"luck":1}},{"t":"follow_up","moment":"a3_3_rush","delay_hours":36,"chance":100}]},{"w":50,"text":"He ignores you and goes on to complain loudly to a customer. You stay calm, and your name is mentioned by the wrong people.","tone":"bad","effects":[{"t":"needs","delta":{"stress":5}},{"t":"follow_up","moment":"a3_3_rival","delay_hours":36,"chance":100}]}]}]$j$::jsonb, 0, 0, 482),
($t$a3_2_friends$t$, $t$Word spreads$t$, $t$Your friends told their friends, who told their friends. Mama Blessing’s small shed is almost full by lunchtime. She runs between the pots and the customers, shouting for plates. A man at the corner table looks at his watch and sighs.$t$, $t$📣$t$, $t$Mama Blessing$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"help","label":"Roll up your sleeves and serve","path":{"goodwill":3,"hustle":1},"outcomes":[{"w":70,"text":"You serve plates, wash cups and pour water for an hour. Customers laugh at you. Mama Blessing pays you in food and a tight hug.","tone":"good","effects":[{"t":"needs","delta":{"energy":-10,"hunger":15,"social":8}},{"t":"skill_xp","skill":"cooking","xp":4},{"t":"follow_up","moment":"a3_3_rush","delay_hours":36,"chance":100}]},{"w":30,"text":"A customer takes a photo and posts it. \"Best new buka in Ekenwan!\" Strangers start arriving.","tone":"twist","effects":[{"t":"needs","delta":{"energy":-8,"social":10}},{"t":"path","delta":{"luck":1}},{"t":"follow_up","moment":"a3_3_rush","delay_hours":36,"chance":100}]}]},{"id":"leave","label":"Pay and leave, you have things to do","path":{"hustle":1},"outcomes":[{"w":100,"text":"You wave goodbye. Mama Blessing waves back with a bowl in one hand and a ladle in the other. She will manage.","tone":"good","effects":[{"t":"needs","delta":{"stress":1}},{"t":"follow_up","moment":"a3_3_rival","delay_hours":48,"chance":100}]}]}]$j$::jsonb, 0, 0, 483),
($t$a3_2_loan$t$, $t$The stock arrives$t$, $t$Mama Blessing buys fresh stock with your ₦3,000: rice, tomatoes, a better pot. The next day her stew is deeper, richer and louder. She calls you over and gives you a plate. "Eat. Tell me the truth."$t$, $t$📦$t$, $t$Mama Blessing$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"truth","label":"Tell her honestly how it tastes","path":{"goodwill":1,"hustle":1},"outcomes":[{"w":70,"text":"It is delicious, and you tell her. She tears up, then asks you to taste again, just to be sure.","tone":"good","effects":[{"t":"needs","delta":{"hunger":20,"social":6}},{"t":"follow_up","moment":"a3_3_rush","delay_hours":36,"chance":100}]},{"w":30,"text":"It needs a little more pepper, and you say so. She adds it, tastes it and shouts for joy. The whole shed smells like Sunday.","tone":"twist","effects":[{"t":"needs","delta":{"hunger":20,"social":8}},{"t":"skill_xp","skill":"cooking","xp":4},{"t":"follow_up","moment":"a3_3_rush","delay_hours":36,"chance":100}]}]},{"id":"praise","label":"Say it is perfect, to encourage her","path":{"goodwill":2},"outcomes":[{"w":60,"text":"She beams. The next customers get the same stew, and they love it too.","tone":"good","effects":[{"t":"needs","delta":{"hunger":18,"social":6}},{"t":"follow_up","moment":"a3_3_rush","delay_hours":36,"chance":100}]},{"w":40,"text":"The stew is a bit salty. A customer quietly pushes his plate away. You wish you had been more honest.","tone":"bad","effects":[{"t":"needs","delta":{"hunger":10,"stress":3}},{"t":"follow_up","moment":"a3_3_rival","delay_hours":36,"chance":100}]}]}]$j$::jsonb, 0, 0, 484),
($t$a3_3_rush$t$, $t$Too many customers$t$, $t$It is a Saturday and Mama Blessing’s shed is bursting. She is out of rice by 2 pm and the queue is still long. People mutter. A child starts to cry. Mama Blessing looks at you, panic in her eyes.$t$, $t$🍽️$t$, $t$Mama Blessing$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"run","label":"Run to the market for more rice","cost":1500,"path":{"hustle":2,"goodwill":2},"outcomes":[{"w":60,"text":"You sprint to Oba Market, haggle in record time and return with a bag of rice on your shoulder. The queue cheers.","tone":"good","effects":[{"t":"needs","delta":{"energy":-12,"social":8}},{"t":"skill_xp","skill":"fitness","xp":4},{"t":"follow_up","moment":"a3_4_end","delay_hours":48,"chance":100}]},{"w":40,"text":"The market is crowded and you are late. By the time you return, half the queue has gone. Mama Blessing smiles bravely.","tone":"bad","effects":[{"t":"needs","delta":{"energy":-12,"stress":5}},{"t":"follow_up","moment":"a3_4_end","delay_hours":48,"chance":100}]}]},{"id":"calm","label":"Calm the queue and share the wait","path":{"goodwill":2},"outcomes":[{"w":55,"text":"You go down the line with small apologies and a joke. People laugh, and many wait. Someone brings drinks for everybody.","tone":"twist","effects":[{"t":"needs","delta":{"social":10,"fun":6}},{"t":"path","delta":{"luck":1}},{"t":"follow_up","moment":"a3_4_end","delay_hours":48,"chance":100}]},{"w":45,"text":"The queue grumbles, but stays. Mama Blessing is able to cook more rice, and the day is saved.","tone":"good","effects":[{"t":"needs","delta":{"social":6,"stress":3}},{"t":"follow_up","moment":"a3_4_end","delay_hours":48,"chance":100}]}]}]$j$::jsonb, 0, 0, 485),
($t$a3_3_rival$t$, $t$The rival’s offer$t$, $t$The owner of the bigger buka corners you outside Mama Blessing’s shed. "I like your style," he says smoothly. "Come and work with me. Better pay, a real kitchen, no shed. And tell Mama Blessing she should close before she loses more money."$t$, $t$🤨$t$, $t$The owner of the big buka$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"refuse","label":"Refuse politely and tell him off","path":{"goodwill":3,"trouble":-1},"outcomes":[{"w":60,"text":"He frowns and leaves. Mama Blessing, who heard everything, squeezes your hand and says nothing, which says it all.","tone":"good","effects":[{"t":"needs","delta":{"social":8,"stress":-3}},{"t":"street_cred","delta":1},{"t":"follow_up","moment":"a3_4_end","delay_hours":48,"chance":100}]},{"w":40,"text":"He smiles coldly and says he will remember you. You feel a small shadow follow you down the road.","tone":"bad","effects":[{"t":"needs","delta":{"stress":6}},{"t":"follow_up","moment":"a3_4_end","delay_hours":48,"chance":100}]}]},{"id":"listen","label":"Hear his offer fully","path":{"hustle":2,"goodwill":-1},"outcomes":[{"w":40,"text":"It is a real offer. You decline, but his number is saved, and a door is slightly open.","tone":"good","effects":[{"t":"needs","delta":{"social":3}},{"t":"skill_xp","skill":"business","xp":4},{"t":"follow_up","moment":"a3_4_end","delay_hours":48,"chance":100}]},{"w":60,"text":"It is more of a threat than an offer. You tell Mama Blessing, and she thanks you for your honesty.","tone":"bad","effects":[{"t":"needs","delta":{"stress":6,"social":3}},{"t":"follow_up","moment":"a3_4_end","delay_hours":48,"chance":100}]}]},{"id":"accept","label":"Take his job and leave Mama Blessing","path":{"goodwill":-4,"hustle":2},"outcomes":[{"w":70,"text":"You earn a bit more, but the first time you pass Mama Blessing’s shed, she looks away. The money feels lighter than the guilt.","tone":"bad","effects":[{"t":"cash","amount":1500},{"t":"needs","delta":{"stress":8,"social":-6}},{"t":"street_cred","delta":-1},{"t":"follow_up","moment":"a3_4_end","delay_hours":72,"chance":100}]},{"w":30,"text":"Within a week you discover the rival’s kitchen is short-staffed and short-tempered. You quit and come back to Mama Blessing, who forgives you slowly.","tone":"twist","effects":[{"t":"needs","delta":{"stress":6,"energy":-6}},{"t":"follow_up","moment":"a3_4_end","delay_hours":72,"chance":100}]}]}]$j$::jsonb, 0, 0, 486),
($t$a3_4_end$t$, $t$A share in the shed$t$, $t$Mama Blessing closes the shed early on Sunday and calls you to sit. She has a small paper envelope, a plate of her best rice and a smile that is slowly turning into tears. "Because of you," she says, "my children will start the new term on time. Please, accept this."$t$, $t$🎊$t$, $t$Mama Blessing$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"accept","label":"Accept with gratitude","path":{"goodwill":1},"outcomes":[{"w":65,"text":"You share the plate, the envelope contains ₦4,000, and her children bring you a small drawing. You keep the drawing forever.","tone":"good","effects":[{"t":"cash","amount":4000},{"t":"needs","delta":{"hunger":20,"social":12,"stress":-8}},{"t":"skill_xp","skill":"cooking","xp":5}]},{"w":35,"text":"Inside the envelope is ₦4,000 and a small note: \"Free plates for you for life.\" The next week, she keeps a plate for you every Saturday.","tone":"twist","effects":[{"t":"cash","amount":4000},{"t":"needs","delta":{"hunger":18,"social":14}},{"t":"path","delta":{"luck":1,"goodwill":1}}]}]},{"id":"refuse","label":"Say that she should keep the money","path":{"goodwill":3,"family":1},"outcomes":[{"w":55,"text":"She insists, you refuse, and finally you agree on a compromise: ₦1,500 and a long hug. You leave with the best plate of rice you have ever eaten.","tone":"good","effects":[{"t":"cash","amount":1500},{"t":"needs","delta":{"hunger":22,"social":12,"stress":-8}}]},{"w":45,"text":"She cries, and presses a bag of fresh plantain into your arms. Her children wave all the way to the end of the road.","tone":"twist","effects":[{"t":"item","id":"plantain","qty":2},{"t":"needs","delta":{"hunger":14,"social":12,"stress":-8}},{"t":"path","delta":{"luck":2}}]}]}]$j$::jsonb, 0, 0, 487),
($t$a4_1$t$, $t$A note under your door$t$, $t$You find a small folded note under your door. In neat handwriting: "You smile like a Sunday morning. I see you at the junction every day. I am too shy to say it." There is no name. Somewhere in your chest, a small drum begins.$t$, $t$💌$t$, $t$An unknown hand$t$, $t$daily$t$, $j${"partner":false,"min_days":2}$j$::jsonb, $j${"family":0.3}$j$::jsonb, $j$[{"id":"reply","label":"Leave a friendly reply note","path":{"family":1,"goodwill":1},"outcomes":[{"w":60,"text":"You write \"Thank you, whoever you are\" and leave it on your door. Next morning, the note is gone, and a small flower is in its place.","tone":"good","effects":[{"t":"needs","delta":{"social":6,"fun":8}},{"t":"follow_up","moment":"a4_2_reply","delay_hours":36,"chance":100}]},{"w":40,"text":"You write a long, flowery reply, then a short, plain one. You leave the plain one. The next morning, it has a smiley drawn on it.","tone":"funny","effects":[{"t":"needs","delta":{"social":5,"fun":10}},{"t":"follow_up","moment":"a4_2_reply","delay_hours":36,"chance":100}]}]},{"id":"ask","label":"Ask your neighbours who it could be","path":{"hustle":1},"outcomes":[{"w":60,"text":"Three neighbours claim to know, and name three different people. By the end, you are sure nobody knows.","tone":"funny","effects":[{"t":"needs","delta":{"fun":8,"social":6}},{"t":"follow_up","moment":"a4_2_ask","delay_hours":36,"chance":100}]},{"w":40,"text":"An old neighbour winks and says, \"Be patient, my dear.\" That is all you get.","tone":"good","effects":[{"t":"needs","delta":{"social":5}},{"t":"follow_up","moment":"a4_2_ask","delay_hours":36,"chance":100}]}]},{"id":"ignore","label":"Ignore it. Probably a prank","path":{"hustle":-1,"family":-1},"outcomes":[{"w":100,"text":"You put the note in a drawer and do not think about it. For about a week.","tone":"good","effects":[{"t":"needs","delta":{"stress":1}},{"t":"follow_up","moment":"a4_2_ignore","delay_hours":120,"chance":100}]}]}]$j$::jsonb, 90, 0.6, 488),
($t$a4_2_reply$t$, $t$A second note$t$, $t$There is a new note, with a small wildflower taped to it: "Thank you for answering. If you want to know who I am, come to King’s Square on Sunday at five. I will wear a green scarf. If you do not come, I will understand."$t$, $t$🌼$t$, $t$An unknown hand$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"go","label":"Go to King’s Square on Sunday","path":{"family":2,"hustle":1},"outcomes":[{"w":70,"text":"You arrive early, nervous, and watch the fountain. At five, a person in a green scarf looks across the square and smiles.","tone":"good","effects":[{"t":"needs","delta":{"social":6,"fun":6,"stress":4}},{"t":"follow_up","moment":"a4_3_meet","delay_hours":72,"chance":100}]},{"w":30,"text":"You arrive early. So does someone with a green scarf. You both laugh at how early you came and the conversation flows from there.","tone":"twist","effects":[{"t":"needs","delta":{"social":8,"fun":8}},{"t":"path","delta":{"luck":1}},{"t":"follow_up","moment":"a4_3_meet","delay_hours":72,"chance":100}]}]},{"id":"friend","label":"Take a friend along for safety","path":{"family":1,"trouble":-1},"outcomes":[{"w":60,"text":"Your friend hides behind a pillar with the world’s worst disguise. You try not to look. The green scarf waves, and your friend nearly falls over.","tone":"funny","effects":[{"t":"needs","delta":{"fun":10,"social":6}},{"t":"follow_up","moment":"a4_3_meet","delay_hours":72,"chance":100}]},{"w":40,"text":"Your friend waits across the road. You meet the writer, it goes well, and you both agree to meet again.","tone":"good","effects":[{"t":"needs","delta":{"social":8,"stress":-3}},{"t":"follow_up","moment":"a4_3_meet","delay_hours":72,"chance":100}]}]},{"id":"skip","label":"Do not go, it is too much","path":{"family":-1,"hustle":-1},"outcomes":[{"w":100,"text":"You stay home. A bit regretful, a bit relieved. A week later there is another small note in your door.","tone":"good","effects":[{"t":"needs","delta":{"stress":2}},{"t":"follow_up","moment":"a4_3_prank","delay_hours":120,"chance":100}]}]}]$j$::jsonb, 0, 0, 489),
($t$a4_2_ask$t$, $t$A clue from the junction$t$, $t$Your questions have travelled. A girl who sells pure water at the junction beckons you over with a grin. "I know who it is," she says. "I will tell you for free, but you must promise not to scream." You promise. She leans closer.$t$, $t$🕵️$t$, $t$The junction$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"listen","label":"Listen to what she knows","path":{"hustle":1},"outcomes":[{"w":55,"text":"\"It is the person from the buka,\" she whispers. \"They get shy when you pass.\" You go home with a new smile and a new plan.","tone":"twist","effects":[{"t":"needs","delta":{"social":6,"fun":8}},{"t":"follow_up","moment":"a4_3_meet","delay_hours":48,"chance":100}]},{"w":45,"text":"\"It is... me,\" she says, laughing, and runs away. A prank! You stand in the road laughing for a full minute.","tone":"funny","effects":[{"t":"needs","delta":{"fun":12}},{"t":"follow_up","moment":"a4_3_prank","delay_hours":48,"chance":100}]}]},{"id":"wait","label":"Say you prefer to wait and see","path":{"faith":1,"family":1},"outcomes":[{"w":100,"text":"She shrugs, impressed. \"You are patient,\" she says. \"Good. Patience is attractive.\" You walk away smiling.","tone":"good","effects":[{"t":"needs","delta":{"social":4,"stress":-2}},{"t":"follow_up","moment":"a4_3_meet","delay_hours":72,"chance":100}]}]}]$j$::jsonb, 0, 0, 490),
($t$a4_2_ignore$t$, $t$The notes come back$t$, $t$A new note, thicker than the first: "I understand if you think I am silly. I will not leave more notes, but I will say this: I have admired your kindness from a distance. If you ever want to talk, I will be at the buka, same time as always."$t$, $t$📝$t$, $t$An unknown hand$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"buka","label":"Go to the buka at the same time","path":{"family":1,"goodwill":1},"outcomes":[{"w":100,"text":"You sit with your rice and look around. Someone looks up, blushes and lowers their eyes. It starts there.","tone":"good","effects":[{"t":"needs","delta":{"social":6,"fun":6}},{"t":"follow_up","moment":"a4_3_meet","delay_hours":48,"chance":100}]}]},{"id":"leave","label":"Leave it, you are not interested","path":{"goodwill":1},"outcomes":[{"w":100,"text":"You are kind, clear and quiet. The notes stop. A few weeks later you receive a small card that says, simply, \"Thank you for your honesty.\"","tone":"good","effects":[{"t":"needs","delta":{"stress":-2,"social":3}},{"t":"follow_up","moment":"a4_4_end","delay_hours":120,"chance":100}]}]}]$j$::jsonb, 0, 0, 491),
($t$a4_3_meet$t$, $t$King’s Square$t$, $t$The fountain in King’s Square is lit, people walk in pairs and a hawker sells roasted corn. The person with the green scarf is a quiet, kind-eyed person who has been writing notes to you for a month. They are blushing furiously.$t$, $t$⛲$t$, $t$King’s Square$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"warm","label":"Be warm and curious","path":{"family":2,"goodwill":1},"outcomes":[{"w":60,"text":"You talk for two hours. By the end, your corn is cold and your phone is full of a new number.","tone":"good","effects":[{"t":"needs","delta":{"social":12,"fun":12,"hunger":5}},{"t":"skill_xp","skill":"charisma","xp":4},{"t":"follow_up","moment":"a4_4_end","delay_hours":72,"chance":100}]},{"w":40,"text":"You discover you both love the same old songs. They hum one. You hum along. A small, happy moment you will keep.","tone":"twist","effects":[{"t":"needs","delta":{"social":14,"fun":14}},{"t":"path","delta":{"luck":1,"family":1}},{"t":"follow_up","moment":"a4_4_end","delay_hours":72,"chance":100}]}]},{"id":"friends","label":"Be honest: you want to be friends first","path":{"goodwill":2,"faith":1},"outcomes":[{"w":75,"text":"They nod, relieved. \"Friends first,\" they say. \"I can do friends.\" The evening turns easy and funny.","tone":"good","effects":[{"t":"needs","delta":{"social":10,"fun":8,"stress":-4}},{"t":"follow_up","moment":"a4_4_end","delay_hours":72,"chance":100}]},{"w":25,"text":"They look hurt for a second, then smile politely. \"I understand.\" The walk home is quiet.","tone":"bad","effects":[{"t":"needs","delta":{"social":2,"stress":4}},{"t":"follow_up","moment":"a4_4_end","delay_hours":72,"chance":100}]}]},{"id":"joke","label":"Make jokes to hide your nerves","path":{"hustle":1},"outcomes":[{"w":70,"text":"Your jokes are terrible and they laugh anyway. By the end of the evening your cheeks hurt.","tone":"funny","effects":[{"t":"needs","delta":{"fun":14,"social":8}},{"t":"follow_up","moment":"a4_4_end","delay_hours":72,"chance":100}]},{"w":30,"text":"One joke lands wrongly. A pause. You apologise and they forgive you, but the mood has changed.","tone":"bad","effects":[{"t":"needs","delta":{"social":3,"stress":6}},{"t":"follow_up","moment":"a4_4_end","delay_hours":72,"chance":100}]}]}]$j$::jsonb, 0, 0, 492),
($t$a4_3_prank$t$, $t$It was a prank$t$, $t$Your phone lights up with a dozen messages: "WE GOT YOU!" It was your friends, writing the notes and leaving them. Someone sends a laughing emoji. Someone sends a voice note. Somebody sends a photo of you reading the first note.$t$, $t$🎭$t$, $t$Your friends$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"laugh","label":"Laugh it off and plan a revenge","path":{"goodwill":1,"hustle":1},"outcomes":[{"w":70,"text":"You laugh until you cry and plan an even bigger prank for next week. Friendship, tested and confirmed.","tone":"funny","effects":[{"t":"needs","delta":{"fun":14,"social":12}},{"t":"follow_up","moment":"a4_4_end","delay_hours":72,"chance":100}]},{"w":30,"text":"You laugh. Then one friend admits that one note was theirs and real. You both pretend nothing happened.","tone":"good","effects":[{"t":"needs","delta":{"social":8,"fun":8}},{"t":"path","delta":{"luck":1}},{"t":"follow_up","moment":"a4_4_end","delay_hours":72,"chance":100}]}]},{"id":"hurt","label":"Admit it hurt a little","path":{"family":1,"goodwill":1},"outcomes":[{"w":70,"text":"They are quiet, then sorry. \"We did not mean to hurt you,\" one says. A warm, honest conversation follows.","tone":"good","effects":[{"t":"needs","delta":{"social":8,"stress":-4}},{"t":"follow_up","moment":"a4_4_end","delay_hours":72,"chance":100}]},{"w":30,"text":"The joking stops and an awkward silence takes its place. It will pass, but not today.","tone":"bad","effects":[{"t":"needs","delta":{"social":-2,"stress":5}},{"t":"follow_up","moment":"a4_4_end","delay_hours":72,"chance":100}]}]}]$j$::jsonb, 0, 0, 493),
($t$a4_4_end$t$, $t$After the notes$t$, $t$Weeks pass. The notes, the square, the green scarf and the laughter have all become a small chapter of your life. You wake one Sunday and realise you are looking forward to the week in a way you had not before. Life in Benin has a way of sneaking up on you.$t$, $t$🌅$t$, $t$Your street$t$, $t$chapter$t$, $j${}$j$::jsonb, $j${}$j$::jsonb, $j$[{"id":"keep","label":"Keep the connection alive","path":{"family":2,"goodwill":1},"outcomes":[{"w":60,"text":"You send a message. A reply arrives in a minute, with a smile you can read through text. Small things grow.","tone":"good","effects":[{"t":"needs","delta":{"social":10,"fun":8,"stress":-6}}]},{"w":40,"text":"Someone knocks at your door with two plates of jollof and a shy smile. \"I was in the area,\" they say. They were not.","tone":"twist","effects":[{"t":"needs","delta":{"social":12,"fun":10,"hunger":15}},{"t":"path","delta":{"luck":1}}]}]},{"id":"open","label":"Stay open to whatever comes","path":{"faith":1,"hustle":1},"outcomes":[{"w":100,"text":"You do not force anything. You walk, you wave, you say hello to more people. Gently, the world opens.","tone":"good","effects":[{"t":"needs","delta":{"social":8,"stress":-5,"fun":5}}]}]}]$j$::jsonb, 0, 0, 494),
($t$d_neighbours_watch$t$, $t$The street is asking questions$t$, $t$Two men with torches and notebooks from the neighbourhood watch stop you at the gate. "Good evening. People say they have seen a few strange things around your area lately. We are just asking everyone. You understand."$t$, $t$👀$t$, $t$The street watch$t$, $t$daily$t$, $j${"path":{"trouble":{"min":15}}}$j$::jsonb, $j${"trouble":1}$j$::jsonb, $j$[{"id":"open","label":"Answer openly and offer tea","path":{"trouble":-3,"goodwill":1},"outcomes":[{"w":65,"text":"They leave with a cup of tea in each hand and a note that says \"all clear\". The street starts to look at you differently.","tone":"good","effects":[{"t":"needs","delta":{"social":5,"stress":-3}},{"t":"street_cred","delta":1}]},{"w":35,"text":"One of the watchmen says quietly, \"People talk, but you have been decent. Keep it that way.\" You will.","tone":"twist","effects":[{"t":"needs","delta":{"stress":-3}},{"t":"path","delta":{"luck":1}}]}]},{"id":"snap","label":"Snap that it is none of their business","path":{"trouble":3,"goodwill":-2},"outcomes":[{"w":75,"text":"They note it down. Your name goes into a different notebook now, the one the street reads aloud on Sundays.","tone":"bad","effects":[{"t":"needs","delta":{"stress":10,"social":-6}},{"t":"street_cred","delta":-2}],"path_w":{"trouble":1}},{"w":25,"text":"They shrug and move on. Nothing happens, but you feel eyes on your back for days.","tone":"good","effects":[{"t":"needs","delta":{"stress":6}}]}]},{"id":"fix","label":"Promise to change your ways","path":{"trouble":-4,"faith":1},"outcomes":[{"w":100,"text":"You mean it, and they can tell. One of them pats your shoulder: \"A person can always start again.\"","tone":"good","effects":[{"t":"needs","delta":{"stress":-5,"social":6}},{"t":"street_cred","delta":1}]}]}]$j$::jsonb, 35, 1, 495),
($t$d_community_honour$t$, $t$The compound honours you$t$, $t$On Sunday afternoon the whole compound gathers in the yard. Mr. Osaze clears his throat and says that "certain people have made this place better by their kindness". Everyone turns and looks at you. Somebody starts clapping.$t$, $t$🏅$t$, $t$The compound$t$, $t$daily$t$, $j${"path":{"goodwill":{"min":15}}}$j$::jsonb, $j${"goodwill":1}$j$::jsonb, $j$[{"id":"humble","label":"Thank them humbly and share the credit","path":{"goodwill":2,"faith":1},"outcomes":[{"w":60,"text":"They hand you a small envelope from the compound contribution and a big plate of jollof. You share the jollof with everybody.","tone":"good","effects":[{"t":"cash","amount":3000},{"t":"needs","delta":{"social":12,"hunger":15,"stress":-6}}]},{"w":40,"text":"The envelope has ₦3,000, and a handwritten card signed by twelve families. You frame it later.","tone":"twist","effects":[{"t":"cash","amount":3000},{"t":"needs","delta":{"social":14,"stress":-8}},{"t":"path","delta":{"luck":1}},{"t":"street_cred","delta":2}]}]},{"id":"speech","label":"Give a short speech","path":{"hustle":1,"goodwill":1},"outcomes":[{"w":60,"text":"Your speech goes on a little too long, and a child interrupts to ask about the cake. Everyone laughs. You end with a toast.","tone":"funny","effects":[{"t":"needs","delta":{"social":12,"fun":10}},{"t":"skill_xp","skill":"charisma","xp":4}]},{"w":40,"text":"Your words are short and warm. The compound applauds, and Mr. Osaze wipes his eyes.","tone":"good","effects":[{"t":"needs","delta":{"social":12,"stress":-5}},{"t":"street_cred","delta":1}]}]},{"id":"slip","label":"Slip away, you hate attention","path":{"hustle":-1},"outcomes":[{"w":100,"text":"You tiptoe out the back. A few minutes later a child brings you a plate. \"From everybody,\" she says, and runs.","tone":"good","effects":[{"t":"needs","delta":{"social":6,"hunger":12}}]}]}]$j$::jsonb, 45, 1, 496)
